import type { Scene } from "./timeline.d";

export const timeline: Scene[] = [{"id": "ghf-06500101-1", "date": "0650-01-01", "year": "c.650", "location": "St Dochdwy's, Llandough", "locationType": "other", "description": "", "narration": "St Dochdwy's church, beside the farm, is thought to stand on the site of an early monastery. This rests on the family's account; the published reference is still awaited, and how the site relates to the two parcels is unclear.", "scenes": [{"character": "FAMILY HISTORIAN", "icon": "farmer", "side": "left", "color": "#999", "text": "The church next to the farm is said to have begun as a monastery.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "Then we need the published reference before we rely on it.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Archaeology and Heritage (greathousefarmwiki.wordpress.com/archaeology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-11000101-1", "date": "1100-01-01", "year": "1100", "location": "Llandough, Glamorgan", "locationType": "other", "description": "", "narration": "Robert Fitzhamon grants the lordship of Llandough to the Walsche family, establishing feudal control of the area that includes the future Great House Farm.", "scenes": [{"character": "ROBERT FITZHAMON", "icon": "worker", "side": "left", "color": "#999", "text": "I grant Walsche the Llandough lordship to manage, tax and defend.", "position": {"x": 0, "y": 0}}, {"character": "LORD WALSCHE", "icon": "worker", "side": "right", "color": "#999", "text": "We now hold Llandough and its revenues under Fitzhamon's grant.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-12000101-1", "date": "1200-01-01", "year": "1200s", "location": "Llandough Church", "locationType": "other", "description": "", "narration": "The site beside St Dochdwy's church at Llandough is occupied in the medieval period: sherds of 12th- to early 14th-century pottery were later found on the slope just north-east of the house. The house itself, Tŷ Mawr ('Great House'), was classed by the Royal Commission as a sub-medieval house, probably 17th-century, possibly with a medieval core.", "scenes": [{"character": "MASTER MASON", "icon": "worker", "side": "left", "color": "#999", "text": "There has been building beside St Dochdwy's for generations.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL FARMER", "icon": "worker", "side": "right", "color": "#999", "text": "The pottery on the slope says folk have lived here a long time.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-12150101-1", "date": "1215-01-01", "year": "1215", "location": "Monastic Estate", "locationType": "other", "description": "", "narration": "Tewkesbury Abbey and the Prior of Cardiff hold Great House and its lands, taking tithes and agricultural income from Llandough for over three centuries.", "scenes": [{"character": "ABBOT'S STEWARD", "icon": "cleric", "side": "left", "color": "#999", "text": "Llandough's produce and tithes are entered as revenue for the abbey.", "position": {"x": 0, "y": 0}}, {"character": "VILLAGE WOMAN", "icon": "worker", "side": "right", "color": "#999", "text": "Our harvest and church payments go into the abbey's accounts.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-12150102-1", "date": "1215-01-02", "year": "1215", "location": "Great House Site — NE Slope", "locationType": "other", "description": "", "narration": "Archaeological evidence confirms medieval occupation of the Great House site: sherds of C12th, C13th and early C14th pottery on the steep slope immediately NE of the house. The HER classifies Great House as a sub-medieval direct-entry house with clear affinities to Brynwell, a medieval farmhouse in neighbouring Leckwith parish. A reported 'armour' find is dealt with under c.1870 and c.1880.", "scenes": [{"character": "HER OFFICER", "icon": "archive", "side": "left", "color": "#2d5016", "text": "C12th-C14th pottery sherds on the NE slope confirm continuous occupation from that date.", "position": {"x": 0, "y": 0}}, {"character": "RCAHMW INSPECTOR", "icon": "archive", "side": "right", "color": "#6b3a1f", "text": "The core of the house may have been medieval — cross-passage end-chimney plan with masonry partitions and external wall batter.", "position": {"x": 0, "y": 0}}, {"character": "ARCHAEOLOGIST", "icon": "worker", "side": "left", "color": "#2d5016", "text": "Medieval ironwork found under the rear wing floor c.1880, now at the National Museum of Wales.", "position": {"x": 0, "y": 0}}, {"character": "RCAHMW INSPECTOR", "icon": "archive", "side": "right", "color": "#6b3a1f", "text": "Great House has affinities with Brynwell, a medieval farmhouse in Leckwith, also modernised by the Bute Estate in the C19th.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio", "RCAHMW Inventory Vol IV Part 2", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Sherds of C12th, C13th, and early C14th pottery found on steep slope immediately NE of house", "House classified as sub-medieval direct-entry type with cross-passage end-chimney plan", "External wall batter on N side — affinities with Brynwell farmhouse in Leckwith (medieval, pre-Reformation)", "Ogee-stopped beam with torus — a form of decoration not particularly common in Glamorgan (Inventory Map 50)"], "report": []}}, {"id": "ghf-14440101-1", "date": "1444-01-01", "year": "1444", "location": "Raglan", "locationType": "other", "description": "", "narration": "Sir William Thomas Herbert of Raglan purchases the manor and lordship of Llandough and St Mary Church, bringing them into the Herbert family's territorial network.", "scenes": [{"character": "SIR WILLIAM THOMAS", "icon": "worker", "side": "left", "color": "#999", "text": "We have bought Llandough manor and added it to the Herbert estates.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL PRIEST", "icon": "cleric", "side": "right", "color": "#999", "text": "Llandough's manorial control passes to the Herbert family of Raglan.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-15360101-1", "date": "1536-01-01", "year": "1536", "location": "Legal Chambers", "locationType": "other", "description": "", "narration": "Sir Edward Carne, a lawyer and diplomat, purchases the Llandough lordship from the 2nd Earl of Worcester, continuing high‑status lay ownership of the manor.", "scenes": [{"character": "SIR EDWARD CARNE", "icon": "worker", "side": "left", "color": "#999", "text": "I have acquired the Llandough lordship from the Earl of Worcester.", "position": {"x": 0, "y": 0}}, {"character": "LLANDOUGH TENANT", "icon": "worker", "side": "right", "color": "#999", "text": "The legal lord of Llandough changes from Worcester's line to Carne.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-15390101-1", "date": "1539-01-01", "year": "1539", "location": "Great House", "locationType": "other", "description": "", "narration": "Henry VIII's Dissolution of the Monasteries transfers Tewkesbury's ecclesiastical holdings, including Llandough lands, to the Crown as secular property.", "scenes": [{"character": "ROYAL COMMISSIONER", "icon": "lawyer", "side": "left", "color": "#999", "text": "These former Tewkesbury lands now vest in the Crown by statute.", "position": {"x": 0, "y": 0}}, {"character": "OLDER VILLAGER", "icon": "worker", "side": "right", "color": "#999", "text": "Control of local church lands moves from abbey to Crown authority.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-15430101-1", "date": "1543-01-01", "year": "1543", "location": "Estate Office", "locationType": "other", "description": "", "narration": "Post‑Dissolution grants move Llandough through lay owners and into the wider Herbert–Pembroke orbit, later feeding into what becomes the Bute estate.", "scenes": [{"character": "HERBERT ESTATE LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "Llandough is one of several manors consolidated into our estate.", "position": {"x": 0, "y": 0}}, {"character": "SMALLHOLDER", "icon": "worker", "side": "right", "color": "#999", "text": "The superior owner changes again on paper; our tenure is recorded under them.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-15520101-1", "date": "1552-01-01", "year": "1552", "location": "Manorial Court", "locationType": "other", "description": "", "narration": "The Bute–Pembroke estate treats itself as manorial lord, issuing leases for Llandough Farm (about 166 acres) and recording long‑standing occupiers as tenants.", "scenes": [{"character": "MANOR STEWARD", "icon": "worker", "side": "left", "color": "#999", "text": "We register Llandough occupiers as tenants in the Bute–Pembroke books.", "position": {"x": 0, "y": 0}}, {"character": "TENANT FARMER", "icon": "worker", "side": "right", "color": "#999", "text": "Our occupation is recorded as a tenancy under the Bute–Pembroke estate.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-15600101-1", "date": "1560-01-01", "year": "1560", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "The Vaughan family, a minor gentry family, become the chief freehold farmers of Great House from the mid C16th. They occupy the property for over two centuries, until the late C18th. Several memorial inscriptions relating to the family are preserved in Llandough parish church and churchyard. The Vaughans represent the established local gentry class who held the chief freehold farm of the parish for generations.", "scenes": [{"character": "VAUGHAN PATRIARCH", "icon": "farmer", "side": "left", "color": "#6b3a1f", "text": "Our family, the Vaughans, are now established as the chief freehold farmers of Great House.", "position": {"x": 0, "y": 0}}, {"character": "PARISH CLERIC", "icon": "cleric", "side": "right", "color": "#4a2d70", "text": "The Vaughan family memorials will be preserved in our church and churchyard for centuries to come.", "position": {"x": 0, "y": 0}}, {"character": "VAUGHAN PATRIARCH", "icon": "farmer", "side": "left", "color": "#6b3a1f", "text": "We are minor gentry — not the highest rank, but we hold this land as freeholders, not tenants.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL RECORDER", "icon": "worker", "side": "right", "color": "#999", "text": "The Vaughans will hold Great House from the mid C16th through to the late C18th — more than two centuries.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Vaughan family: minor gentry family, chief freehold farmers from mid C16th to late C18th", "Several memorial inscriptions in Llandough church and churchyard"], "report": []}}, {"id": "ghf-16670101-1", "date": "1667-01-01", "year": "1667", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "According to Mary Williams's own statement, the Williams family's occupation of Great House begins in 1667. No earlier written source has yet been found; family tradition remembers the entry as a purchase, while estate records treat the family as tenants.", "scenes": [{"character": "WILLIAMS ANCESTOR", "icon": "farmer", "side": "left", "color": "#999", "text": "I paid a large court fine to enter Great House as our family's holding.", "position": {"x": 0, "y": 0}}, {"character": "HERBERT STEWARD", "icon": "worker", "side": "right", "color": "#999", "text": "Our roll shows the Williams entry as a manorial lease, not freehold.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS ANCESTOR", "icon": "farmer", "side": "left", "color": "#999", "text": "But this is our home now, purchased with honest coin for our heirs.", "position": {"x": 0, "y": 0}}, {"character": "HERBERT STEWARD", "icon": "worker", "side": "right", "color": "#999", "text": "The Court Baron record will show this as leasehold under our lordship.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS ANCESTOR", "icon": "farmer", "side": "left", "color": "#999", "text": "We have the receipt. Our children will know we bought this land.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend that their occupation from 1667 amounted to ownership in all but name, and that this claim was asserted for more than 300 years. An earlier written source is still being sought."}, {"id": "ghf-16770101-1", "date": "1677-01-01", "year": "1677", "location": "Estate Records", "locationType": "other", "description": "", "narration": "Through marriage, the Llandough lordship passes into the Talbot estate at Penrice and Margam, while the Williams family continues in occupation at Great House.", "scenes": [{"character": "TALBOT HEIR", "icon": "worker", "side": "left", "color": "#999", "text": "By marriage we acquire Llandough among our Glamorgan holdings.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FAMILY MEMBER", "icon": "farmer", "side": "right", "color": "#999", "text": "The superior lord's name changes; our occupation at Great House continues.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-17700101-1", "date": "1770-01-01", "year": "1770", "location": "Estate Transfer", "locationType": "other", "description": "", "narration": "Great House passes through elite owners, including Valentine Morris and Sir Mark Wood, before later consolidation into the Bute estate.", "scenes": [{"character": "VALENTINE MORRIS", "icon": "worker", "side": "left", "color": "#999", "text": "I treat Great House as one of several Glamorgan assets for income.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL LABOURER", "icon": "worker", "side": "right", "color": "#999", "text": "Estate owners change; our local work under their control continues.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-17940101-1", "date": "1794-01-01", "year": "1794", "location": "Title Office", "locationType": "other", "description": "", "narration": "Sir Mark Wood acquires title and treats Great House as a revenue asset within his wider property portfolio, before it is surveyed and later taken into Bute hands.", "scenes": [{"character": "SIR MARK WOOD", "icon": "worker", "side": "left", "color": "#999", "text": "I hold Great House as an income‑producing property in my portfolio.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FARMER", "icon": "farmer", "side": "right", "color": "#999", "text": "Our long‑term home appears in someone else's accounts as an asset.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18000101-1", "date": "1800-01-01", "year": "1800", "location": "Great House", "locationType": "other", "description": "", "narration": "In the early C19th, the freehold of Great House is acquired by the Bute Estate — one of the largest landed estates in Wales, controlled by the Marquess of Bute. The manorial courts for Llandough and Leckwith are held in Great House, confirming its historic role as a seat of local governance. The Bute Estate modernises the property in the C19th, as it did with neighbouring Brynwell farmhouse in Leckwith.", "scenes": [{"character": "BUTE ESTATE AGENT", "icon": "worker", "side": "left", "color": "#6b3a1f", "text": "The Bute Estate now holds the freehold of Great House. We will modernise the property.", "position": {"x": 0, "y": 0}}, {"character": "COURT OFFICIAL", "icon": "worker", "side": "right", "color": "#4a2d70", "text": "The manorial courts for Llandough and Leckwith shall be held in Great House from this time.", "position": {"x": 0, "y": 0}}, {"character": "BUTE ESTATE AGENT", "icon": "worker", "side": "left", "color": "#6b3a1f", "text": "We will also modernise Brynwell in Leckwith, which shares Great House medieval origins.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL TENANT", "icon": "farmer", "side": "right", "color": "#999", "text": "The Bute Estate are new landlords. They hold the freehold now.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio", "RCAHMW Inventory Vol IV Part 2"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Bute Estate acquired freehold in early C19th", "Manorial courts for Llandough and Leckwith held in Great House", "Bute Estate modernised the house in the C19th"], "report": []}}, {"id": "ghf-18180101-1", "date": "1818-01-01", "year": "1818", "location": "Estate Records", "locationType": "other", "description": "", "narration": "Lambert Williams of Cardiff enters formal written agreements with the Bute estate between 1818 and 1835, evidencing the Williams family as a recognised legal entity in local property dealings.", "scenes": [{"character": "LAMBERT WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "These written agreements show I deal with the Bute estate directly.", "position": {"x": 0, "y": 0}}, {"character": "BUTE ESTATE AGENT", "icon": "worker", "side": "right", "color": "#999", "text": "We sign deeds with Lambert Williams over Llandough premises, 1818–1835.", "position": {"x": 0, "y": 0}}, {"character": "LAMBERT WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "These documents record our position for future generations to cite.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18180101-2", "date": "1818-01-01", "year": "1818", "location": "Estate Accounts", "locationType": "other", "description": "", "narration": "Chief rents of Llandough are transferred into the manorial rental accounts, simplifying estate bookkeeping and packaging obligations for future buyers.", "scenes": [{"character": "ESTATE ACCOUNTANT", "icon": "worker", "side": "left", "color": "#999", "text": "We combine Llandough chief rents into the manorial rental column.", "position": {"x": 0, "y": 0}}, {"character": "COTTAGER", "icon": "worker", "side": "right", "color": "#999", "text": "Our payments are re‑labelled on paper, but the amounts still fall on us.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18200101-1", "date": "1820-01-01", "year": "1820", "location": "Estate Offices", "locationType": "other", "description": "", "narration": "A land exchange between the Marquess of Bute and Lord Plymouth in Llandough consolidates Great House within Bute's controlled block of estates.", "scenes": [{"character": "BUTE REPRESENTATIVE", "icon": "worker", "side": "left", "color": "#999", "text": "This exchange secures Llandough parcels firmly within the Bute estate.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL OBSERVER", "icon": "worker", "side": "right", "color": "#999", "text": "New memoranda and surveys mark Bute as main landowner here.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18210101-1", "date": "1821-01-01", "year": "1821", "location": "Rent Collection", "locationType": "other", "description": "", "narration": "Llandough and Cogan appear in Bute rentals from 1821 onward, consolidating manorial rents under a single administrative ledger controlled by the estate.", "scenes": [{"character": "RENT COLLECTOR", "icon": "worker", "side": "left", "color": "#999", "text": "The Bute estate now logs Llandough and Cogan in the master rental.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FARMER", "icon": "farmer", "side": "right", "color": "#999", "text": "We pay to them, though this land has been ours for generations past.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18240101-1", "date": "1824-01-01", "year": "1824", "location": "Survey Office", "locationType": "other", "description": "", "narration": "Following Sir Mark Wood's property auction, surveyor David Stewart records Great House Farm under the alias 'Cedfin' in the Bute estate survey of Glamorgan holdings.", "scenes": [{"character": "SURVEYOR STEWART", "icon": "builder", "side": "left", "color": "#999", "text": "I record this property as Great House Farm, alias Cedfin, in Bute accounts.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS OCCUPANT", "icon": "farmer", "side": "right", "color": "#999", "text": "The name on their maps matters little; we know who lives and works here.", "position": {"x": 0, "y": 0}}, {"character": "SURVEYOR STEWART", "icon": "builder", "side": "left", "color": "#999", "text": "Tithes of Llandough purchased in 1824 are now under Bute ownership.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18400101-1", "date": "1840-01-01", "year": "1840", "location": "Estate Registry", "locationType": "other", "description": "", "narration": "Census and tithe records shift terminology from 'Great House' to 'Great House Farm,' downgrading the property from a seat of governance to a commercial agricultural unit.", "scenes": [{"character": "CENSUS CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "I enter this as Great House Farm, removing the designation of Court House.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS ELDER", "icon": "farmer", "side": "right", "color": "#999", "text": "They rename our ancestral seat to erase our status and heritage claim.", "position": {"x": 0, "y": 0}}, {"character": "ESTATE LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "A farm designation supports our treatment of occupants as tenant farmers.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS ELDER", "icon": "farmer", "side": "right", "color": "#999", "text": "This administrative sleight-of-hand obscures generations of our standing.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend that re-describing Tŷ Mawr from manorial court house to farm house eroded their standing and obscured the property's significance."}, {"id": "ghf-18580101-1", "date": "1858-01-01", "year": "1858", "location": "Llandough Church Farm", "locationType": "other", "description": "", "narration": "About 1858, while foundations are dug for new buildings at Llandough Church Farm, workmen find a medieval iron spearhead and a rowel spur, with about six skeletons. The bones are reburied near the stile on the south side of the church. The finds lie in the 100-metre square beside the church that also holds the 1994 cemetery site.", "scenes": [{"character": "WORKMAN", "icon": "worker", "side": "left", "color": "#999", "text": "Bones, and old iron with them. A spearhead and a spur.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "Reburied by the stile, south of the church. The same ground the 1994 diggers would reach.", "position": {"x": 0, "y": 0}}], "sources": ["GHF-E106-R33-A1 — 1931 letter, Museum Wales file 63.24 (https://greathousefarmwiki.wordpress.com/evidence-library/ghf-e106-r33-a1-1931-letter-museum-wales-file-63-24/)", "Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18700101-1", "date": "1870-01-01", "year": "c.1870", "location": "Great House — Dining Room", "locationType": "other", "description": "", "narration": "Family tradition holds that a soldier in armour, with horse, lance and small shield, was found under the dining-room floor. A Daily Telegraph article of 16 April 1974 dates the find to 'about 1870', and RCAHMW holds a note of the story. No primary record of the find has been located; Museum Wales says the similar medieval objects in its collection came from Church Farm, Llandough, in 1858.", "scenes": [{"character": "WILLIAMS FAMILY HEAD", "icon": "farmer", "side": "left", "color": "#999", "text": "We've found a soldier in armour under the floor!", "position": {"x": 0, "y": 0}}, {"character": "FAMILY MEMBER", "icon": "worker", "side": "right", "color": "#999", "text": "This proves the site is ancient and of great historical importance.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL ANTIQUARIAN", "icon": "worker", "side": "left", "color": "#999", "text": "Fascinating, but without a record the authorities will treat it as a story.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FAMILY HEAD", "icon": "farmer", "side": "right", "color": "#999", "text": "Then the family will remember it, until someone looks properly.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family regard the tradition as evidence of the site's antiquity that was never investigated. The Wiki records it as a documented tradition, not a proven find."}, {"id": "ghf-18760101-1", "date": "1876-01-01", "year": "1876", "location": "Estate Offices", "locationType": "other", "description": "", "narration": "From 1876 the Bute Estate lets about 33 acres that had formed part of Great House Farm for the Llandough Limeworks, which work until about 1912. How that land relates to the family's two parcels is still being tested.", "scenes": [{"character": "BUTE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "We sever this land for the Limeworks. It's ours to lease commercially.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FARMER", "icon": "farmer", "side": "right", "color": "#999", "text": "But we live here! You cannot carve up land we've held for two centuries.", "position": {"x": 0, "y": 0}}, {"character": "BUTE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "Estate records show no Williams ownership—only occupation under our lease.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS FARMER", "icon": "farmer", "side": "right", "color": "#999", "text": "Our 1667 receipt and occupation prove our right to this property.", "position": {"x": 0, "y": 0}}, {"character": "BUTE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "Manorial records prevail. You are tenants, not owners, under our title.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family allege they permitted quarrying in exchange for absolute freehold of their land parcel. This oral agreement was never formally recorded — a pattern of convenient documentation gaps."}, {"id": "ghf-18770101-1", "date": "1877-01-01", "year": "1877", "location": "Bute Estate Office", "locationType": "other", "description": "", "narration": "Mary's statement records that the Bute Estate serves notice to quit, then sells the farmhouse and about 10 acres to the quarryman Daniel Thomas, keeping about 9 acres of fields. The Williams family hold tenancies from both. On the family's reconstruction this creates two parcels: the house (Parcel A) and the eastern fields (Parcel B). The deed is missing.", "scenes": [{"character": "BUTE ESTATE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "The farmhouse and ten acres go to Daniel Thomas. The estate keeps the fields.", "position": {"x": 0, "y": 0}}, {"character": "JOHN WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Then we rent the house from Thomas and the fields from Bute. Two landlords, two parcels.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend the 1877 sale took the house parcel out of the Bute title chain for good, so it never passed to WGR or BP. The deed is missing, and the claim is being tested against the records."}, {"id": "ghf-18771106-1", "date": "1877-11-06", "year": "1877", "location": "Glamorgan Archives", "locationType": "other", "description": "", "narration": "On 6 November 1877 the Bute Estate grants John Williams a counterpart lease. On the family's reconstruction it covers the fields (Parcel B). The lease is held at Glamorgan Archives and is still to be obtained.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "A Bute counterpart lease to John Williams, dated 6 November 1877.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "That should show exactly which land Bute kept.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18800101-1", "date": "1880-01-01", "year": "1880", "location": "Estate Records", "locationType": "other", "description": "", "narration": "The property is systematically rebranded from 'Court House' to 'Grange' to 'Farm' in successive records, demoting occupants from gentry with tenure to mere tenant farmers.", "scenes": [{"character": "ESTATE CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "We now list it simply as a farm, eliminating all reference to Court House.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS DESCENDANT", "icon": "farmer", "side": "right", "color": "#999", "text": "This linguistic erasure strips our family of its historic manorial standing.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18800101-2", "date": "1880-01-01", "year": "1880", "location": "Great House — Rear Wing", "locationType": "other", "description": "", "narration": "R.F. Suggett's December 1988 note in the HER records a report of 'armour' found under the floor of the rear wing c.1880, and suggests it may be the medieval ironwork at the National Museum. Museum Wales has since said those objects were found at Church Farm, Llandough, in 1858, and that it holds nothing similar from Great House Farm.", "scenes": [{"character": "WORKMAN", "icon": "worker", "side": "left", "color": "#6b3a1f", "text": "We found armour under the floor of the rear wing! Looks medieval to me.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY MEMBER", "icon": "farmer", "side": "right", "color": "#2d5016", "text": "This proves Great House is more than a simple farm — it has a medieval past!", "position": {"x": 0, "y": 0}}, {"character": "MUSEUM CURATOR", "icon": "archive", "side": "left", "color": "#4a2d70", "text": "We will take this medieval ironwork into the National Museum collection for study and preservation.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL HISTORIAN", "icon": "worker", "side": "right", "color": "#4a2d70", "text": "Another clue to Great House deeper history, though the full truth will not be revealed until long after this house is gone.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio — Supplementary Notes (R.F. Sugget, December 1988)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Suggett (Dec 1988): report of 'armour' under rear-wing floor c.1880; may be the medieval ironwork at the National Museum", "Amgueddfa Cymru (2026): the objects are stated to have been found at Church Farm, Llandough, in 1858", "Museum holds nothing similar from Great House Farm"], "report": []}}, {"id": "ghf-18911111-1", "date": "1891-11-11", "year": "1891", "location": "Llandough — Court Report", "locationType": "other", "description": "", "narration": "On 11 November 1891 three geese are stolen from \"Mr. John Williams, Great House Farm, Llandough\". The newspaper report of the court case is contemporary evidence that John Williams was occupying the farm.", "scenes": [{"character": "COURT REPORTER", "icon": "archive", "side": "left", "color": "#999", "text": "Three geese taken from John Williams of Great House Farm, Llandough.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "A court report from 1891 that names him at the farm. That is a record, not a memory.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n01) — GHF-E090-N01"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-18970501-1", "date": "1897-05-01", "year": "1897", "location": "Great House Farm / Lavernock Point", "locationType": "other", "description": "", "narration": "Family tradition holds that Thomas Williams of Great House carted Guglielmo Marconi and his equipment to Lavernock Point, where Marconi's May 1897 trials sent wireless signals across the Bristol Channel to Flat Holm. The trials are independently documented; the family's part in them has not yet been proved.", "scenes": [{"character": "THOMAS WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "I cart Mr Marconi and his equipment to Lavernock Point each day from Great House.", "position": {"x": 0, "y": 0}}, {"character": "GUGLIELMO MARCONI", "icon": "worker", "side": "right", "color": "#999", "text": "Without a horse and cart, these experiments could not proceed.", "position": {"x": 0, "y": 0}}, {"character": "THOMAS WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "They may call me a carter. But this farm has been ours for generations.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19050223-1", "date": "1905-02-23", "year": "1905", "location": "HM Land Registry — WA231076 File", "locationType": "other", "description": "", "narration": "A Bute conveyance dated 23 February 1905 later appears on the WA231076 registration file and is noted on the woodland title WA735527. On the wiki's current interpretation it concerns Parcel A; what it conveyed has still to be confirmed.", "scenes": [{"character": "LAND REGISTRY CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "A Bute conveyance of 23 February 1905 is listed among the deeds on this file.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Then the deed itself should show which land Bute was dealing with in 1905.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19080101-1", "date": "1908-01-01", "year": "1908", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Mary's grandfather dies, and John Williams takes over both tenancies, the house from the Thomas side and the fields from Bute (Mary's statement).", "scenes": [{"character": "JOHN WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "I take on both tenancies now, the house and the fields.", "position": {"x": 0, "y": 0}}, {"character": "NEIGHBOUR", "icon": "worker", "side": "right", "color": "#999", "text": "Two landlords for one farm. That will cause trouble one day.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19100101-1", "date": "1910-01-01", "year": "1910–11", "location": "Frederick Buckler — Birth", "locationType": "other", "description": "", "narration": "Frederick Buckler is born in 1910 or 1911. The year is worked back from his death in 1967 at the age of 56; his birth and death certificates are still awaited.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Died 1967, aged 56, puts his birth in 1910 or 1911.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "We will order the certificates to settle it.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Frederick Buckler (greathousefarmwiki.wordpress.com/frederick-buckler/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19130810-1", "date": "1913-08-10", "year": "1913", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Mary Williams is born at Great House Farm on 10 August 1913, the daughter of John Williams. She lives there all her life.", "scenes": [{"character": "MIDWIFE", "icon": "worker", "side": "left", "color": "#999", "text": "A healthy daughter! The Williams line at Great House continues.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS MATRIARCH", "icon": "farmer", "side": "right", "color": "#999", "text": "She will know her heritage and defend this land when her time comes.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19160201-1", "date": "1916-02-01", "year": "1916", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "In February 1916 the Bute Estate lets the whole farm to John Williams on a yearly tenancy. The tenancy is known from the 1987 judgment and the 1989 Commission decision; no original document has been located.", "scenes": [{"character": "JOHN WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "The Marquess of Bute grants me the agricultural tenancy of Great House Farm.", "position": {"x": 0, "y": 0}}, {"character": "MARQUESS OF BUTE", "icon": "worker", "side": "right", "color": "#999", "text": "We record John Williams as agricultural tenant at Great House Farm.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19240515-1", "date": "1924-05-15", "year": "1924", "location": "HM Land Registry — WA231076 File", "locationType": "other", "description": "", "narration": "An agreement dated 15 May 1924 appears on the WA231076 registration file. Its contents and effect are unknown, and it is not yet clear which parcel it concerns.", "scenes": [{"character": "LAND REGISTRY CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "An agreement of 15 May 1924 is listed on the file. The document itself is not described.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Until we see it, we cannot say what it did or which land it covered.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19280101-1", "date": "1928-01-01", "year": "1928", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "The last quarry machinery leaves, and a final rent of about £4 is paid to Alfred Thomas. Mary recalled that her father 'regarded the farm as his own' from then on. The receipt is missing.", "scenes": [{"character": "ALFRED THOMAS", "icon": "worker", "side": "left", "color": "#999", "text": "That's the last rent, about four pounds.", "position": {"x": 0, "y": 0}}, {"character": "JOHN WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "And after this, the farm is ours.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend that twelve years' rent-free occupation of the house parcel from 1928 was complete by about 1940."}, {"id": "ghf-19311122-1", "date": "1931-11-22", "year": "1931", "location": "Cogan Pill", "locationType": "other", "description": "", "narration": "On 22 November 1931 a letter headed Cogan Pill records the 1858 Church Farm finds for the National Museum. The spur and spearhead are later donated in 1963 and accessioned as 63.24. In 2026 the Museum will at first say it holds nothing relevant.", "scenes": [{"character": "LETTER WRITER", "icon": "archive", "side": "left", "color": "#999", "text": "Found at Llandough Church Farm, about 1858, when digging foundations.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The Museum had this file all along.", "position": {"x": 0, "y": 0}}], "sources": ["GHF-E106-R33 — Museum Wales reply (https://greathousefarmwiki.wordpress.com/records-access-chronology/foi-reply-register/ghf-e106-r33-amgueddfa-cymru-reply-further-collections-search-following-8-september-2026-foi/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19360101-1", "date": "1936-01-01", "year": "1936", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Mary Williams marries Frederick Buckler, who joins her at the farmhouse. They have seven children, among them William (Billy). After Frederick's death in 1967 Mary reverts to her maiden name, Williams.", "scenes": [{"character": "MARY WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "I marry Frederick Buckler, and he comes to live with us at the farmhouse.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "This house is your family's; I'll help keep the farm going.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL PRIEST", "icon": "cleric", "side": "left", "color": "#999", "text": "Mary Williams of Great House Farm weds Frederick Buckler this day.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19370101-1", "date": "1937-01-01", "year": "c.1937–40", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Frederick and Mary's eldest son is born at about this time. The date rests on family belief; his birth entry has still to be traced.", "scenes": [{"character": "FAMILY MEMBER", "icon": "farmer", "side": "left", "color": "#999", "text": "The eldest boy was born a year or so after the wedding.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "The GRO index will give the exact date once the entry is found.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19380101-1", "date": "1938-01-01", "year": "1938", "location": "Bute Estate Office", "locationType": "other", "description": "", "narration": "The Bute Estate conveys its reversion on the 1916 tenancy to Western Ground Rents Ltd (WGR). The family contend this was not a sale of the whole farm: on their reconstruction the house parcel (Parcel A) had passed out of Bute hands in 1877.", "scenes": [{"character": "BUTE ESTATE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "The reversion on the Williams tenancy passes to Western Ground Rents.", "position": {"x": 0, "y": 0}}, {"character": "JOHN WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Then what did they sell? The house was never theirs to sell after 1877.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19390501-1", "date": "1939-05-01", "year": "1939", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "In May 1939 WGR grants John Williams a revised tenancy. Its plan shows the fields east of the house. The family contend it covered the eastern fields (Parcel B) only, not the farmhouse.", "scenes": [{"character": "WGR AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "Here is your revised tenancy, with the plan attached.", "position": {"x": 0, "y": 0}}, {"character": "JOHN WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "The plan shows the fields to the east. The house is not on it.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19400101-1", "date": "1940-01-01", "year": "c.1940", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "The family contend that by about 1940 twelve years of rent-free occupation of the house parcel, counted from the last rent paid in 1928, would have been complete.", "scenes": [{"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "No rent on the house since 1928. Twelve years on, the family say their title by possession was complete.", "position": {"x": 0, "y": 0}}, {"character": "ESTATE AGENT", "icon": "worker", "side": "right", "color": "#999", "text": "The landlord will say the family were tenants of the whole farm throughout.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — 1938–39: Sale to WGR and the Revised Tenancy (greathousefarmwiki.wordpress.com/1939-revised-tenancy/#c1940)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: This is the family's contention. It depends on the house parcel being outside the 1916 and 1939 tenancies after 1928, which is still being tested against the records."}, {"id": "ghf-19440101-1", "date": "1944-01-01", "year": "1944", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "The War Agricultural Executive Committee is dissatisfied with the farm, and Frederick Buckler runs it as manager for John Williams (Mary's statement).", "scenes": [{"character": "WAEC OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "Production must improve. The war needs every acre.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "I'll run the farm for John. We'll meet the quota.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19480101-1", "date": "1948-01-01", "year": "c.1948–49", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "William (Billy) Buckler is born at the farm. He lives there until the eviction of 1988.", "scenes": [{"character": "MARY WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "Another son, born here in the farmhouse.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "He will grow up on this land, as you did.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/#william)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19490202-1", "date": "1949-02-02", "year": "1949", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "On 2 February 1949 John Williams's tenancy is surrendered and Frederick Buckler's unwritten yearly tenancy from WGR begins.", "scenes": [{"character": "FAMILY SOLICITOR", "icon": "worker", "side": "left", "color": "#999", "text": "The tenancy is to be transferred from John Williams to Frederick Buckler.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "I am to take over the agricultural tenancy from John Williams.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19500601-1", "date": "1950-06-01", "year": "1950", "location": "Great House Farm — Blanket Box", "locationType": "other", "description": "", "narration": "In June 1950 a Penarth estate agent places a lodger at the farmhouse. He stays about two years, and later tells Mary he took 'the papers which were in the blanket box including the agreement relating to the farm' and gave them to the agent. Mary links the loss to WGR's first possession application.", "scenes": [{"character": "LODGER", "icon": "worker", "side": "left", "color": "#999", "text": "I took the papers from the blanket box, the farm agreement too, and gave them to the agent.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Those were the papers that proved the farm was ours.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend the documents that proved their title were taken from their home shortly before the first possession proceedings."}, {"id": "ghf-19521010-1", "date": "1952-10-10", "year": "1952", "location": "Landlords' Agents' Office", "locationType": "other", "description": "", "narration": "On 10 October 1952 the landlords' agents decide not to proceed with the letting to Frederick Buckler.", "scenes": [{"character": "LANDLORDS' AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "We have decided not to proceed with the letting to Mr Buckler.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Then what am I, if not your tenant?", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Frederick Buckler (greathousefarmwiki.wordpress.com/frederick-buckler/#tenancy-1949)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19530101-1", "date": "1953-01-01", "year": "1953", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Frederick Buckler makes the last known rent payment around 1953. From this point, the family pay nothing to any claimant, and their occupation becomes wholly adverse under limitation law.", "scenes": [{"character": "BILLY BUCKLER (YOUNG)", "icon": "farmer", "side": "left", "color": "#999", "text": "This has been our family home for as long as anyone can remember.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "We owe rent to no one. Your grandfather secured this place for our family.", "position": {"x": 0, "y": 0}}], "sources": [], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19550202-1", "date": "1955-02-02", "year": "1955", "location": "Title Office / Great House Farm", "locationType": "other", "description": "", "narration": "On 2 February 1955 the High Court makes a possession order against Frederick Buckler alone, worded for the whole farm. Mary is not a party. On 4 July 1955 possession is taken of everything except the farmhouse and garden, and the family stay on in the house.", "scenes": [{"character": "REGISTRAR", "icon": "worker", "side": "left", "color": "#999", "text": "We invite owners to register titles under the land registration system.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "I wish to register our ownership; we have occupied since 1667 and pay no rent.", "position": {"x": 0, "y": 0}}, {"character": "REGISTRAR", "icon": "worker", "side": "left", "color": "#999", "text": "Do you have a deed, conveyance, or grant? Without documentary title we cannot register.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "We have family history, occupation since 1667, and our ancestor's entry receipt.", "position": {"x": 0, "y": 0}}, {"character": "REGISTRAR", "icon": "worker", "side": "left", "color": "#999", "text": "Without formal documentation we cannot register your claimed ownership.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend that the order concerned the farmland Frederick had rented, but was worded for the whole farm, treating two parcels as one. Mary, who claimed the house, was not a party."}, {"id": "ghf-19590101-1", "date": "1959-01-01", "year": "1959", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "In 1959 Mary refuses a tenancy of the farmhouse and garden and asserts ownership. When she tells WGR that documents prove her title, none can be produced: the family papers had been taken from the blanket box in 1950–52.", "scenes": [{"character": "MARY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "The Williams family has held Great House for centuries. I assert our hereditary ownership.", "position": {"x": 0, "y": 0}}, {"character": "LEGAL ADVISOR", "icon": "worker", "side": "right", "color": "#999", "text": "The claim rests on ancestral title predating the Bute estate records.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19610329-1", "date": "1961-03-29", "year": "1961", "location": "HM Land Registry — WA231076 File", "locationType": "other", "description": "", "narration": "A deed dated 29 March 1961 appears on the WA231076 registration file. Its contents are unknown, and it is not yet clear which parcel it concerns.", "scenes": [{"character": "LAND REGISTRY CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "A deed of 29 March 1961 is listed on the file.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Another document we know exists but have never seen.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19621211-1", "date": "1962-12-11", "year": "1962", "location": "Cardiff County Court", "locationType": "other", "description": "", "narration": "On 11 December 1962 Judge Temple Morris QC, in Cardiff County Court, orders possession of the farmhouse and garden, with mesne profits since 1955, against Frederick and Mary Buckler on WGR's claim. The order is not enforced before 1974. An open question is whether the county court had jurisdiction, given its £100 rateable-value limit in 1962.", "scenes": [{"character": "COURT CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "Possession order granted, 11 December 1962. Registered against the farmhouse and garden.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "We will not leave. This is our home. We will appeal any order they obtain.", "position": {"x": 0, "y": 0}}, {"character": "RECORDS CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "The landlord holds the order but has not yet moved to enforce it.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "right", "color": "#999", "text": "We file a defence based on adverse possession under the Limitation Act 1939.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "Our family has been here since 1667. No court order can make us leave.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19630101-1", "date": "1963-01-01", "year": "1963", "location": "Llandough — Utility Trench", "locationType": "other", "description": "", "narration": "In 1963 three skeletons are reported in utility-trench works near the church. The account comes from a secondary research file; the underlying 1963 record is still being traced. In the same year the National Museum takes in the spur and spearhead found at Church Farm in 1858.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Three skeletons in a trench, and nobody kept the report. We are still looking for it.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Every time the ground near the church is opened, burials come up.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (https://greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19630601-1", "date": "1963-06-01", "year": "1963", "location": "Cardiff County Court", "locationType": "other", "description": "", "narration": "In June 1963 the mesne profits under the 1962 order are partly enforced against Frederick, and committal proceedings follow.", "scenes": [{"character": "COURT OFFICER", "icon": "lawyer", "side": "left", "color": "#999", "text": "Mesne profits are due under the 1962 order.", "position": {"x": 0, "y": 0}}, {"character": "FREDERICK BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "We pay what we can. We are not leaving the house.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19640101-1", "date": "1964-01-01", "year": "1964", "location": "Family Account", "locationType": "other", "description": "", "narration": "A cousin's account says the eldest son sold 'our land parcel' some time in 1964–67. No document has been found, and the account remains unverified.", "scenes": [{"character": "COUSIN", "icon": "worker", "side": "left", "color": "#999", "text": "I always heard the eldest son sold our land parcel.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY MEMBER", "icon": "farmer", "side": "right", "color": "#999", "text": "Then where is the deed? Nobody has ever seen one.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19650301-1", "date": "1965-03-01", "year": "1965", "location": "WGR Agents' Office", "locationType": "other", "description": "", "narration": "In January–March 1965 WGR refuses to let Frederick the fields. On 2 March it offers a weekly tenancy of the farmhouse to 'Mrs Williams'. It is never signed.", "scenes": [{"character": "WGR AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "A weekly tenancy of the farmhouse, for Mrs Williams to sign.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "I will not sign for my own house.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19670101-1", "date": "1967-01-01", "year": "1967", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Frederick Buckler dies aged 56. Mary reverts to her maiden name, Williams, and stays on in the farmhouse.", "scenes": [{"character": "MARY WILLIAMS", "icon": "farmer", "side": "left", "color": "#999", "text": "Frederick is gone. I am a Williams again, and this is still my home.", "position": {"x": 0, "y": 0}}, {"character": "NEIGHBOUR", "icon": "worker", "side": "right", "color": "#999", "text": "She'll not be moved, that one.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19680901-1", "date": "1968-09-01", "year": "1968–69", "location": "Great House Farm", "locationType": "other", "description": "", "narration": "Between September 1968 and September 1969 the eldest son's household leaves the farm, according to the family's account.", "scenes": [{"character": "FAMILY MEMBER", "icon": "farmer", "side": "left", "color": "#999", "text": "His family moved out of the farm around then.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "This is the family account; we date it from what relatives remember.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — The Williams / Buckler Family (greathousefarmwiki.wordpress.com/williams-buckler-family/#rumoured-sale)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19691231-1", "date": "1969-12-31", "year": "1969", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "On 31 December 1969 WGR sells to BP Pension Trust Ltd. The conveyance is missing from the Land Registry files released so far.", "scenes": [{"character": "BP SOLICITOR", "icon": "worker", "side": "left", "color": "#999", "text": "BP Pension Trust Ltd now holds the freehold of Great House Farm.", "position": {"x": 0, "y": 0}}, {"character": "ESTATE AGENT", "icon": "worker", "side": "right", "color": "#999", "text": "The farm is sold as part of a portfolio to BP Pension Trust.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19700616-1", "date": "1970-06-16", "year": "1970", "location": "Leckwith Road, Llandough", "locationType": "other", "description": "", "narration": "On 16 June 1970 land by Leckwith Road is registered as village green VG41. The wiki's current reconstruction places it in Parcel A; the boundary has still to be confirmed (timeline ref. GHF-E033-VG41).", "scenes": [{"character": "REGISTRATION OFFICER", "icon": "archive", "side": "left", "color": "#999", "text": "The land by Leckwith Road is entered in the register as village green VG41.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "If the green lies inside the house parcel, it was registered while Mary was living there.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19720725-1", "date": "1972-07-25", "year": "1972", "location": "Planning Office", "locationType": "other", "description": "", "narration": "On 25 July 1972 an earlier planning permission for housing on the site is granted, while Mary Williams is still living in the farmhouse.", "scenes": [{"character": "PLANNING OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "Permission is granted for housing on the site.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Housing, on the land around a house I am living in.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19740101-1", "date": "1974-01-01", "year": "1974", "location": "Great House — Interior", "locationType": "other", "description": "", "narration": "The ground floor of Great House is surveyed in unusual circumstances by H.J. Thomas for the Royal Commission (RCAHMW). Much detail is concealed and the first floor and roof trusses cannot be examined: the house 'remained partially recorded because of problems of access created by an ownership dispute'.", "scenes": [{"character": "H.J.T. (RCAHMW)", "icon": "archive", "side": "left", "color": "#4a2d70", "text": "I have surveyed the ground floor of Great House. The circumstances are most unusual. Much detail is concealed and I cannot access the first floor or roof trusses.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOURCE", "icon": "farmer", "side": "right", "color": "#2d5016", "text": "The ownership dispute means access is restricted. The surveyors cannot see the full house.", "position": {"x": 0, "y": 0}}, {"character": "H.J.T. (RCAHMW)", "icon": "archive", "side": "left", "color": "#4a2d70", "text": "The house will remain partially recorded. Problems of access created by the ownership dispute prevent a complete survey.", "position": {"x": 0, "y": 0}}, {"character": "RCAHMW RECORDER", "icon": "archive", "side": "right", "color": "#6b3a1f", "text": "The Inventory of Farmhouses and Cottages will note that Great House plan was not published because of incomplete information.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio", "RCAHMW Inventory Vol IV Part 2", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Ground floor surveyed in unusual circumstances in 1974 by H.J.T.", "Much detail was concealed — could not examine first floor and roof trusses", "House remained partially recorded because of access problems from ownership dispute", "Great House plan not published in Inventory due to incompleteness of available information"], "report": []}}, {"id": "ghf-19740415-1", "date": "1974-04-15", "year": "1974", "location": "Great House Farm — Open Day", "locationType": "other", "description": "", "narration": "On 15 April 1974 Mary Williams, then 60, opens the farmhouse to the public 'to show what the nation is losing'. Hundreds come. The Daily Telegraph reports next day that planning permission for about 13 houses has been given to the BP Petroleum Pension Trust, that about 1,000 people have signed a petition, and that Mary will refuse to move.", "scenes": [{"character": "MARY WILLIAMS", "icon": "worker", "side": "left", "color": "#999", "text": "I will refuse to move, because not only is this my home, it is part of the nation's heritage.", "position": {"x": 0, "y": 0}}, {"character": "REPORTER", "icon": "worker", "side": "right", "color": "#999", "text": "The ownership has been disputed for years, Mrs Williams?", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "worker", "side": "left", "color": "#999", "text": "For 25 years. But my family has lived here for more than 400 years, and my solicitors tell me I have a valid claim to it.", "position": {"x": 0, "y": 0}}], "sources": ["Daily Telegraph, 16 April 1974, 'Open day to save ancient Welsh house', Godfrey Francis (transcript GHF-E090-N03: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n03)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19740703-1", "date": "1974-07-03", "year": "1974", "location": "Court / Great House Farm", "locationType": "other", "description": "", "narration": "On 3 July 1974 BP Pension Trust brings a new possession action. Mary pleads ownership and the Limitation Act 1939. The action is part-heard and never relisted.", "scenes": [{"character": "COURT CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "BP Pension Trust applies to enforce the 1962 possession order forthwith.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS' SOLICITOR", "icon": "lawyer", "side": "right", "color": "#999", "text": "We file a defence: the landlord's title has been extinguished by adverse possession since 1955.", "position": {"x": 0, "y": 0}}, {"character": "JUDGE", "icon": "lawyer", "side": "left", "color": "#999", "text": "Warrant to issue but not be enforced until 31 October 1974 pending appeal.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "We received a letter offering us a licence to stay rent-free. We never agreed to that.", "position": {"x": 0, "y": 0}}, {"character": "COURT CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "BP Pension Trust's October 1974 licence letter is now on the court record.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend the action was dropped in the face of press support for Mary. BP later relied on licence letters she never asked for and always disputed."}, {"id": "ghf-19740919-1", "date": "1974-09-19", "year": "1974", "location": "Cardiff County Court", "locationType": "other", "description": "", "narration": "On 19 September 1974 the county court judge (Judge Watkin Powell, per the family archive) gives BP leave to enforce the 1962 order, but no warrant is to issue before 31 October. Mary's solicitors appeal because she was given no notice.", "scenes": [{"character": "JUDGE WATKIN POWELL", "icon": "worker", "side": "left", "color": "#999", "text": "Leave is granted to enforce the 1962 possession order.", "position": {"x": 0, "y": 0}}, {"character": "BP BARRISTER", "icon": "worker", "side": "right", "color": "#999", "text": "My Lord, we seek enforcement of the existing possession order.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19741031-1", "date": "1974-10-31", "year": "1974", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "On 31 October 1974 BP Pension Trust Ltd sends Mary letters purporting to licence her to remain at Great House Farm rent-free for life. These letters later decide the case against the family.", "scenes": [{"character": "BP MANAGER", "icon": "worker", "side": "left", "color": "#999", "text": "We issue this licence allowing Mrs Buckler to remain rent-free for life.", "position": {"x": 0, "y": 0}}, {"character": "MARY BUCKLER", "icon": "worker", "side": "right", "color": "#999", "text": "BP says I may stay, but I have never accepted they own this land.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19741031-2", "date": "1974-10-31", "year": "1974", "location": "Great House Farm, Llandough", "locationType": "other", "description": "", "narration": "On 31 October 1974, the day the licence letters are sent, the possession warrant is withdrawn and Mary remains in the farmhouse.", "scenes": [{"character": "COURT OFFICIAL", "icon": "worker", "side": "left", "color": "#999", "text": "The possession warrant is withdrawn. Mrs Buckler may remain in occupation.", "position": {"x": 0, "y": 0}}, {"character": "MARY BUCKLER", "icon": "worker", "side": "right", "color": "#999", "text": "I shall stay at Great House. No warrant will move me from my home.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19741119-1", "date": "1974-11-19", "year": "1970s", "location": "Western Mail — Letters", "locationType": "other", "description": "", "narration": "William Rees writes to the Western Mail ('Grievous loss', dated 19/11/7? in the copy held; the year is unclear) that demolishing Great House Farm would erase the site of the Celtic monastery of St Dochdwy. He traces its descent from Tewkesbury Abbey to the Crown at the Dissolution, then to Herbert and to Bute.", "scenes": [{"character": "WILLIAM REES", "icon": "worker", "side": "left", "color": "#999", "text": "The demolition of Great House Farm would erase from memory one of the early historical sites of Glamorgan.", "position": {"x": 0, "y": 0}}, {"character": "READER", "icon": "worker", "side": "right", "color": "#999", "text": "So the farm marks the old monastery of St Dochdwy?", "position": {"x": 0, "y": 0}}], "sources": ["Western Mail, 'Grievous loss', letter from William Rees, 19/11/7? (transcript GHF-E090-N04: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n04)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19750523-1", "date": "1975-05-23", "year": "1975", "location": "Estate Agent's Office", "locationType": "other", "description": "", "narration": "On 23 May 1975 BP Pension Trust transfers its interest to BP Properties Ltd. Mary maintains that no transfer can defeat the ownership she asserted in court the previous year.", "scenes": [{"character": "ESTATE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "The superior title passes to new holders. Sitting occupants are noted in the file.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "You cannot sell what you do not own! My court case is still pending!", "position": {"x": 0, "y": 0}}, {"character": "ESTATE AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "Our registered title permits this transaction despite the pending occupants' claim.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Adjourned means unresolved—not dismissed! Our adverse possession defence stands!", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19780101-1", "date": "1978-01-01", "year": "1978", "location": "Llandough Roman Villa (separate site)", "locationType": "other", "description": "", "narration": "GGAT excavates the Llandough Roman Villa (PRN 00768s), south of the church, in 1978–79. This is a separate site, not Great House Farm; earlier versions of this timeline wrongly placed the villa on the farm.", "scenes": [{"character": "ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "The villa is south of the church. Great House is to the north.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL RESIDENT", "icon": "worker", "side": "right", "color": "#999", "text": "So the Roman villa and the farm are two different places.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19800522-1", "date": "1980-05-22", "year": "1980", "location": "House of Commons", "locationType": "other", "description": "", "narration": "On 22 May 1980 Ted Rowlands MP tells the House of Commons that Western Ground Rents, 'the most rapacious ground landlord' in South Wales, has been bought by the BP pension fund. The landlord that sued Frederick in 1955 is now inside the BP group.", "scenes": [{"character": "TED ROWLANDS MP", "icon": "lawyer", "side": "left", "color": "#999", "text": "The most rapacious ground landlord, Western Ground Rents, has been bought by the BP pension fund.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "So the landlord of 1955 and the owner of 1987 were one and the same family of companies.", "position": {"x": 0, "y": 0}}], "sources": ["GHF-E090-N16 — Hansard, 22 May 1980 (https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n16)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19821001-1", "date": "1982-10-01", "year": "1982", "location": "GGAT", "locationType": "other", "description": "", "narration": "On 1 October 1982 GGAT tells the planning authority that occupation may continue north of the church, and asks for 'thorough investigative work prior to the development'.", "scenes": [{"character": "GGAT ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "There must be thorough investigative work before any development.", "position": {"x": 0, "y": 0}}, {"character": "PLANNING OFFICER", "icon": "worker", "side": "right", "color": "#999", "text": "Noted for the file.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19821119-1", "date": "1982-11-19", "year": "1982", "location": "Property Transfer", "locationType": "other", "description": "", "narration": "Between 19 and 30 November 1982 BP Pension Trust transfers to BP Properties Ltd, and first registration is applied for (title WA231076); a second application (WA240304) follows on 23 February 1983. Mary Williams is alive and living in the farmhouse throughout. The family contend no inquiry was made of her.", "scenes": [{"character": "BP PROPERTIES LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "We are registered as proprietor of Great House Farm from November 1982.", "position": {"x": 0, "y": 0}}, {"character": "MARY WILLIAMS", "icon": "farmer", "side": "right", "color": "#999", "text": "Another transfer! They keep selling our home while our adverse possession claim stands!", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "Our title is registered. The 1974 licence letter means your claim is not adverse.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "How can you be bona fide when our possession and claim are fully on record?", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "We acquired from the registered proprietor. Your claim is against the prior vendor.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19830223-1", "date": "1983-02-23", "year": "1983", "location": "HM Land Registry — WA240304", "locationType": "other", "description": "", "narration": "On 23 February 1983 BP's solicitors, Linklaters & Paines, apply to register the farmhouse and garden as a separate title, WA240304, and certify that they know of no question or doubt affecting the title. Mary Williams is living in the farmhouse, and her 1974 plea that she owns it has never been decided.", "scenes": [{"character": "LINKLATERS & PAINES", "icon": "lawyer", "side": "left", "color": "#999", "text": "We know of no question or doubt affecting the title.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Mary was sitting in that house, claiming it as her own. That was the question.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "The certificate was given a month before she died.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#first-registration)", "Legal Review, F3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#fraud)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "The family's case is that this registration took in the house parcel without disclosing Mary's ownership claim."}, {"id": "ghf-19830313-1", "date": "1983-03-13", "year": "1983", "location": "GGAT Warehouse, Swansea", "locationType": "other", "description": "", "narration": "On 13 March 1983 a fire at GGAT's Swansea warehouse destroys the finds from the Llandough Roman villa excavation. The villa is a separate site from Great House Farm.", "scenes": [{"character": "ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "Years of finds from the Llandough villa dig have been lost in the fire.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL HISTORIAN", "icon": "worker", "side": "right", "color": "#999", "text": "That was the villa south of the church, not Great House Farm, but it is still a loss to Llandough.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n06) — GHF-E090-N06 (South Wales Echo, 18 March 1983)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19830326-1", "date": "1983-03-26", "year": "1983", "location": "Great House Farm / Legal Office", "locationType": "other", "description": "", "narration": "Mary Williams dies at the farmhouse on 26 March 1983, and her son William (Billy) inherits her claim. The farm agreement had been taken from the family's blanket box in 1950–52, so the family's case rests on Mary's statement and their long occupation.", "scenes": [{"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "The 1667 deed and manorial records that would prove your claim are missing.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "My mother is gone. Where are the documents she always said we had?", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVE CLERK", "icon": "worker", "side": "left", "color": "#999", "text": "We have no record of any Williams conveyance in the Bute estate archives.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Convenient that every document proving our ownership has vanished!", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "Missing deeds raise serious questions. Billy must now claim through her estate.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: First registration was applied for while Mary was alive and in occupation, and she died weeks later. Whether she was ever notified is being pursued with HM Land Registry."}, {"id": "ghf-19830408-1", "date": "1983-04-08", "year": "1983", "location": "HM Land Registry — WA240304", "locationType": "other", "description": "", "narration": "On 8 and 12 April 1983, two weeks after Mary's death, Linklaters and the Land Registry exchange letters on the farmhouse file, including form D23. On 12 May further letters follow on the main title. What the Registry asked about the family's occupation, and what it was told, is in those letters, which the family is now ordering.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Three batches of letters, all after Mary died.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Whatever they asked about us, we were never told.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#first-registration)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19840113-1", "date": "1984-01-13", "year": "1984", "location": "HM Land Registry — WA231076", "locationType": "other", "description": "", "narration": "On 13 January 1984 an application on form A3 is made on the main title and a new edition of the register is issued, four months before BP's writ for possession.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "A change to the register, then the writ. The order matters.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "They were tidying the paperwork before coming for the house.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19840522-1", "date": "1984-05-22", "year": "1984", "location": "BP Properties Offices", "locationType": "other", "description": "", "narration": "On 22 May 1984 BP Properties issues its writ for possession, relying on the 1974 licence letters. In the same year the library copy of the Bute–Thomas deed is reported missing from Cardiff Library.", "scenes": [{"character": "BP PROPERTIES AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "We hold registered title and rely on the 1974 licence letters sent to Mrs Buckler.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "right", "color": "#999", "text": "Those letters were sent by BP Pension Trust in 1974—before you even owned this land!", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "We acquired the benefit of those letters as successors in title to BP Pension Trust.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "My mother never accepted that licence. She disputed it until she died in 1983!", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES AGENT", "icon": "worker", "side": "left", "color": "#999", "text": "She never rejected it in writing. The licence stands under BP Properties Ltd v Buckler.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19860710-1", "date": "1986-07-10", "year": "1986", "location": "High Court, Cardiff", "locationType": "other", "description": "", "narration": "On 10 July 1986 Mr Justice Hollis gives judgment for BP Properties in the High Court at Cardiff. He holds that the 1974 letters gave Mary a valid licence, so she was not in adverse possession. The possession order is suspended for six months.", "scenes": [{"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "We allege fraud in the procurement of title and deliberate document suppression.", "position": {"x": 0, "y": 0}}, {"character": "OPPOSING COUNSEL", "icon": "worker", "side": "right", "color": "#999", "text": "These are serious allegations without proof. Our client's title is registered.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "The missing 1667 deed and identity substitution demand investigation!", "position": {"x": 0, "y": 0}}, {"character": "JUDGE", "icon": "lawyer", "side": "right", "color": "#999", "text": "Your fraud allegations are noted, but this court's task is the adverse possession point.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "Under Takhar v Gracefield, fraud unravels all—but only if investigated!", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19860711-1", "date": "1986-07-11", "year": "1986", "location": "Royal Commission (RCAHMW)", "locationType": "other", "description": "", "narration": "From around 1986–87, during the trial and the appeal, the Royal Commission's correspondence between C. N. Johns and Mrs Buckler goes missing. It may have recorded Mary's own account of her title to an independent public body.", "scenes": [{"character": "RCAHMW", "icon": "archive", "side": "left", "color": "#999", "text": "The Johns–Buckler correspondence has been missing since 1986/87.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Another record lost just when we needed it.", "position": {"x": 0, "y": 0}}], "sources": ["Legal Review, section 1.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#loss-pattern)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19870202-1", "date": "1987-02-02", "year": "1987", "location": "HM Land Registry", "locationType": "other", "description": "", "narration": "On 2 February 1987, while the appeal is pending, an application is made to amalgamate BP's two titles into one.", "scenes": [{"character": "REGISTRY CLERK", "icon": "lawyer", "side": "left", "color": "#999", "text": "An application to amalgamate the two titles.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "While the appeal was still being decided?", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family question why the titles were merged during the appeal; this is being pursued with HM Land Registry."}, {"id": "ghf-19870731-1", "date": "1987-07-31", "year": "1987", "location": "Court of Appeal (Civil Division)", "locationType": "other", "description": "", "narration": "On 31 July 1987 the Court of Appeal (Dillon LJ, with Mustill LJ and Sir Edward Eveleigh) dismisses the appeal in BP Properties Ltd v Buckler. It holds that the 1962 action stopped time running, and that BP's 1974 letters made Mary's possession permissive whether or not she accepted them. It records that her claimed title documents were never produced.", "scenes": [{"character": "DILLON LJ", "icon": "worker", "side": "left", "color": "#999", "text": "The unilateral 1974 licence letter ended adverse possession regardless of acceptance.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY BARRISTER", "icon": "worker", "side": "right", "color": "#999", "text": "My Lords—m'Lord—the licence was never accepted. Adverse possession must have continued!", "position": {"x": 0, "y": 0}}, {"character": "DILLON LJ", "icon": "worker", "side": "left", "color": "#999", "text": "Adverse possession ceased from receipt of the letters. BP Pension Trust's title revived.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY BARRISTER", "icon": "worker", "side": "right", "color": "#999", "text": "The licence substituted Mrs Buckler for Mary Williams without consent or explanation!", "position": {"x": 0, "y": 0}}, {"character": "DILLON LJ", "icon": "worker", "side": "left", "color": "#999", "text": "Appeal dismissed. BP Properties Ltd is entitled to possession of the farm.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The family contend the courts decided possession of the whole farm without the documents bearing on the house parcel ever being before them, and that a licence she rejected was used to defeat her claim."}, {"id": "ghf-19880303-1", "date": "1988-03-03", "year": "1988", "location": "House of Lords", "locationType": "other", "description": "", "narration": "On 3 March 1988 the House of Lords refuses leave to appeal.", "scenes": [{"character": "CLERK OF THE HOUSE", "icon": "lawyer", "side": "left", "color": "#999", "text": "Leave to appeal is refused.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Then there is nowhere left in this country to go.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19880429-1", "date": "1988-04-29", "year": "1988", "location": "Great House Farm — First Eviction Attempt", "locationType": "other", "description": "", "narration": "After the House of Lords refusal the family are given 28 days to find somewhere else to live. On 29 April 1988 five bailiffs and about 15 police arrive. Billy blocks the narrow drive with a tractor, locks the doors and bars the windows.", "scenes": [{"character": "BAILIFF", "icon": "worker", "side": "left", "color": "#999", "text": "You were given twenty-eight days. Time's up.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "We are not leaving our home.", "position": {"x": 0, "y": 0}}], "sources": ["'Chainsaw farmer vows to fight on', Andrew Penman, c. 30 April 1988 (transcript GHF-E090-N07: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n07)", "South Wales Echo, 29 April 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19880429-2", "date": "1988-04-29", "year": "1988", "location": "Great House Farm — Chainsaw Stand-off", "locationType": "other", "description": "", "narration": "The bailiffs smash the gate lock and break at the doors with poleaxes. When an axe comes through a door with his children behind it, Billy starts a chainsaw and pushes it through the door, and the bailiffs back off. After a four-hour stand-off they withdraw. Branwen leaves with the children, aged two, three and four. BP says it regrets the events; the police say they were there to prevent a breach of the peace, not to help the bailiffs.", "scenes": [{"character": "BILLY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "They started smashing the doors with poleaxes. My children were right behind the door when the axe came through.", "position": {"x": 0, "y": 0}}, {"character": "BAILIFF", "icon": "worker", "side": "right", "color": "#999", "text": "Stand back from the door!", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "That's when I started my chainsaw and pushed it through the door. They backed off then.", "position": {"x": 0, "y": 0}}, {"character": "BRANWEN BUCKLER", "icon": "worker", "side": "right", "color": "#999", "text": "I'm taking the children away from here.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "They have got no documents for it. If it's theirs, why have I never paid a penny in rent for it in my life?", "position": {"x": 0, "y": 0}}], "sources": ["'Chainsaw farmer vows to fight on', Andrew Penman, c. 30 April 1988 (transcript GHF-E090-N07: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n07)", "South Wales Echo, 30 April 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19880503-1", "date": "1988-05-03", "year": "1988", "location": "European Commission of Human Rights", "locationType": "other", "description": "", "narration": "On 3 May 1988 William Buckler applies to the European Commission of Human Rights.", "scenes": [{"character": "EUROPEAN RIGHTS LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "You have grounds for an Article 1 Protocol 1 claim on property deprivation.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Finally, a court that might examine what UK courts refused to address!", "position": {"x": 0, "y": 0}}, {"character": "GOVERNMENT SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "Domestic remedies have not been exhausted. The application is premature.", "position": {"x": 0, "y": 0}}, {"character": "EUROPEAN RIGHTS LAWYER", "icon": "lawyer", "side": "right", "color": "#999", "text": "Every UK court refused to determine ownership! What remedy remains?", "position": {"x": 0, "y": 0}}, {"character": "GOVERNMENT SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "Procedural rules bar this application. Domestic courts have ruled conclusively.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19880512-1", "date": "1988-05-12", "year": "1988", "location": "MP's Office", "locationType": "other", "description": "", "narration": "On 12 May 1988 the South Wales Echo reports that the Cardiff MP Alun Michael has asked the Lord Chancellor to look at the case of the farmer who fought off bailiffs with a chainsaw. Billy warns that someone will be killed.", "scenes": [{"character": "ALUN MICHAEL MP", "icon": "worker", "side": "left", "color": "#999", "text": "Lord Chancellor, this case shows serious procedural failures and injustice.", "position": {"x": 0, "y": 0}}, {"character": "LORD CHANCELLOR'S AIDE", "icon": "worker", "side": "right", "color": "#999", "text": "The courts have ruled at the highest level. What grounds justify review?", "position": {"x": 0, "y": 0}}, {"character": "ALUN MICHAEL MP", "icon": "worker", "side": "left", "color": "#999", "text": "Ownership was never determined! That's a fundamental defect in every ruling!", "position": {"x": 0, "y": 0}}, {"character": "LORD CHANCELLOR'S AIDE", "icon": "worker", "side": "right", "color": "#999", "text": "The House of Lords addressed the possession claim comprehensively.", "position": {"x": 0, "y": 0}}, {"character": "ALUN MICHAEL MP", "icon": "worker", "side": "left", "color": "#999", "text": "But possession without ownership determination is procedurally unsafe and unjust!", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 12 May 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19880729-1", "date": "1988-07-29", "year": "1988", "location": "Cadw Offices", "locationType": "other", "description": "", "narration": "On 29 July 1988 Cadw inspects and photographs the farmhouse and barn while considering it for listing. Only those two photographs survive today: Cadw has no file, no notes and no record of who decided, and in 2026 it gave three different explanations of what its code meant.", "scenes": [{"character": "CADW INSPECTOR", "icon": "cleric", "side": "left", "color": "#999", "text": "Farmhouse and barn photographed for the listing survey.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "They came, they took two photographs, and that is all that is left of the file.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Cadw cannot say whether it ever saw the 1974 survey or GGAT's 1982 warning.", "position": {"x": 0, "y": 0}}], "sources": ["Cadw — Forensic Critique v8.0.0 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)", "Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881130-1", "date": "1988-11-30", "year": "1988", "location": "Great House Farm — Forced Entry", "locationType": "other", "description": "", "narration": "BP obtains possession at the end of November 1988; the press places the forced entry on Wednesday 30 November. Within hours, the family say, demolition begins: half the roof is already off one of the outbuildings. Eight other people living at the farm are made homeless with the family.", "scenes": [{"character": "BRANWEN BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "They are already taking the roof off the outbuildings. They will flatten the farmhouse next.", "position": {"x": 0, "y": 0}}, {"character": "BAILIFF", "icon": "worker", "side": "right", "color": "#999", "text": "The property is now in the possession of BP Properties.", "position": {"x": 0, "y": 0}}, {"character": "TENANT", "icon": "worker", "side": "left", "color": "#999", "text": "Billy opened his doors to everyone. Now we're all back on the bus in the lay-by.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "worker", "side": "right", "color": "#999", "text": "This is my family's home.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 30 November 1988, 'Angry scenes as farmer evicted' (transcript GHF-E090-N14: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n14)", "South Wales Echo, 30 November 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "South Wales Echo, 3 December 1988, 'Billy's unhappy family' (transcript GHF-E090-N09: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n09)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881130-2", "date": "1988-11-30", "year": "1988", "location": "Great House Farm — Final Eviction", "locationType": "other", "description": "", "narration": "Billy is taken to Llandough Hospital after the eviction. He is later charged with assaulting two bailiffs, criminal damage, and wanton or furious driving.", "scenes": [{"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "You have no right! Get off this land! Ownership was never decided in any court!", "position": {"x": 0, "y": 0}}, {"character": "POLICE OFFICER", "icon": "worker", "side": "right", "color": "#999", "text": "You are under arrest. Stop resisting. An ambulance has been called.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "A dozen police on the farm and I won't leave—not until someone rules who owns it.", "position": {"x": 0, "y": 0}}, {"character": "POLICE OFFICER", "icon": "worker", "side": "right", "color": "#999", "text": "You face charges of assault on two bailiffs, criminal damage, and furious driving.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "I'll not go to hospital—if I leave they come back and take everything we have left.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 3 December 1988 (transcript GHF-E090-N08: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08)", "South Wales Echo, 3 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881201-1", "date": "1988-12-01", "year": "1988", "location": "Llandough Hospital", "locationType": "other", "description": "", "narration": "Billy Buckler lies injured in Llandough Hospital from the eviction of 30 November. Branwen and the three young children have nowhere to go. The family say Mary's lifetime of possessions, photographs, heirlooms and legal documents were left in the house or scattered in the road.", "scenes": [{"character": "NURSE", "icon": "worker", "side": "left", "color": "#999", "text": "You have significant injuries and must stay. You are not fit to leave.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "If I leave that hospital they'll take the farm. I won't go—not yet.", "position": {"x": 0, "y": 0}}, {"character": "BRANWEN BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "Billy is in Llandough Hospital. I have three children and another coming. We have nothing.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Within hours of getting in they began demolition. Half the outbuilding roof is already off.", "position": {"x": 0, "y": 0}}, {"character": "NURSE", "icon": "worker", "side": "left", "color": "#999", "text": "The police have barred you from the site. You cannot return. Please rest.", "position": {"x": 0, "y": 0}}], "sources": ["Press Archive transcript GHF-E090-N08 (South Wales Echo, 3 December 1988): https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881202-1", "date": "1988-12-02", "year": "1988", "location": "Court", "locationType": "other", "description": "", "narration": "A High Court judge grants an interim injunction that the farmhouse and its contents must not be touched. On 2 December Mr Justice Anthony Evans allows Branwen to collect belongings from the house if BP's solicitors agree. Cadw considers emergency 'spot-listing' and sends an inspector.", "scenes": [{"character": "JUDGE", "icon": "lawyer", "side": "left", "color": "#999", "text": "I grant a temporary injunction against demolition pending further hearing.", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES LAWYER", "icon": "lawyer", "side": "right", "color": "#999", "text": "This injunction frustrates our lawful rights following the Court of Appeal ruling!", "position": {"x": 0, "y": 0}}, {"character": "FAMILY SOLICITOR", "icon": "lawyer", "side": "left", "color": "#999", "text": "Heritage protection and fraud allegations must be examined before demolition!", "position": {"x": 0, "y": 0}}, {"character": "JUDGE", "icon": "lawyer", "side": "right", "color": "#999", "text": "The injunction is limited in time. Cadw must decide on listing promptly.", "position": {"x": 0, "y": 0}}, {"character": "BP PROPERTIES LAWYER", "icon": "lawyer", "side": "left", "color": "#999", "text": "Every delay costs our client money and undermines the finality of judgments.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 3 December 1988, 'History fight to save farm', Peter Bibby (transcript GHF-E090-N08: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n08)", "South Wales Echo, 2 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881203-1", "date": "1988-12-03", "year": "1988", "location": "Cadw — Listing Assessment", "locationType": "other", "description": "", "narration": "Over the weekend of 3 to 5 December 1988 Cadw assesses the farmhouse for emergency spot-listing in about 48 hours, with no access to the interior. Publicly it says it is 'considering' listing, although in July it had coded the house just below the bar.", "scenes": [{"character": "CADW", "icon": "cleric", "side": "left", "color": "#999", "text": "We are considering spot-listing and have sent an inspector.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Forty-eight hours, across a weekend, without setting foot inside.", "position": {"x": 0, "y": 0}}], "sources": ["Cadw — Forensic Critique v8.0.0, Part VI (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881205-1", "date": "1988-12-05", "year": "1988", "location": "Cardiff — Injunction Hearing", "locationType": "other", "description": "", "narration": "On Monday 5 December 1988 Judge Norman Francis dismisses the Bucklers' application to keep the injunction until the European Commission of Human Rights has considered their case. Their solicitor, Colin Jongman, says there are no more steps to take. Cadw says the house is not of sufficient architectural merit to list.", "scenes": [{"character": "JUDGE NORMAN FRANCIS", "icon": "worker", "side": "left", "color": "#999", "text": "It would be novel for a court in this country to hold up the effects of a judgment until the Court of Human Rights rules on it.", "position": {"x": 0, "y": 0}}, {"character": "COLIN JONGMAN", "icon": "worker", "side": "right", "color": "#999", "text": "There are no more steps that can be taken now that the building can be knocked down.", "position": {"x": 0, "y": 0}}, {"character": "JANET HARRIS (BUCKLER)", "icon": "worker", "side": "left", "color": "#999", "text": "It is reputed to be 800 years old, and yet it seems they can destroy it on what is a whim.", "position": {"x": 0, "y": 0}}, {"character": "CADW SPOKESPERSON", "icon": "worker", "side": "right", "color": "#999", "text": "The house is not of sufficient architectural merit.", "position": {"x": 0, "y": 0}}], "sources": ["Western Mail, 6 December 1988, 'Farmer fails in final eviction hearing' (transcript GHF-E090-N10: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n10)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881206-1", "date": "1988-12-06", "year": "1988", "location": "Great House Farm — Demolition", "locationType": "other", "description": "", "narration": "The outbuildings are demolished from 30 November. Just after 4am on 6 December 1988 a twenty-strong team with bulldozers moves in, and by breakfast no building is left standing. Branwen and the three children watch their home flattened.", "scenes": [{"character": "BRANWEN BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "Great House Farm was more than just a house. It was the family history, with all the people born or died there over 400 years.", "position": {"x": 0, "y": 0}}, {"character": "DEMOLITION FOREMAN", "icon": "worker", "side": "right", "color": "#999", "text": "Clear the farmhouse first.", "position": {"x": 0, "y": 0}}, {"character": "BRANWEN BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "Now we are left with no home, no plans, no income and no Christmas.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL OBSERVER", "icon": "worker", "side": "right", "color": "#999", "text": "Bulldozed before breakfast.", "position": {"x": 0, "y": 0}}], "sources": ["'Tears flow as 800 year-old farm house is razed at last', c. 7 December 1988 (transcript GHF-E090-N11: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n11)", "South Wales Echo, 6 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: Demolition destroyed the house before its fabric could be fully recorded: the Royal Commission's survey was never completed, and features were lost in the rubble."}, {"id": "ghf-19881208-1", "date": "1988-12-08", "year": "1988", "location": "Community Meeting", "locationType": "other", "description": "", "narration": "A Vale of Glamorgan councillor, himself a BP pensioner, calls the demolition 'disgusting'. On 8 December Llandough villagers meet their councillors in anger. The family also recall the council's planning chief saying the cleared site looked like a battleground.", "scenes": [{"character": "COUNCILLOR", "icon": "worker", "side": "left", "color": "#999", "text": "As a BP pensioner I say this plainly: what they did here was disgusting.", "position": {"x": 0, "y": 0}}, {"character": "VILLAGER", "icon": "farmer", "side": "right", "color": "#999", "text": "An old house beside our church, flattened before breakfast. We want answers.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 7 and 9 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "1988: Possession and Demolition (https://greathousefarmwiki.wordpress.com/demolition-1988/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881209-1", "date": "1988-12-09", "year": "1988", "location": "Llandough Hospital / Magistrates Court", "locationType": "other", "description": "", "narration": "Police take Billy Buckler from his hospital bed to face charges of assaulting two bailiffs. On 9 December magistrates free him on bail, with conditions keeping him away from the site.", "scenes": [{"character": "POLICE OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "William Buckler, you are taken from hospital to face charges of assault on two bailiffs.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Taken from a hospital bed to answer charges for defending my own home. This is justice?", "position": {"x": 0, "y": 0}}, {"character": "POLICE OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "You face assault, criminal damage, and wanton or furious driving charges.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "I defended my family. They bashed the door in with my children standing behind it.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "Freed on bail. I will fight this to the death. They have no documents for that farm.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 3 and 10 December 1988 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "January 1989 (transcript GHF-E090-N12: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n12)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19881211-1", "date": "1988-12-11", "year": "1988", "location": "Great House Farm — HER Record", "locationType": "archive", "description": "", "narration": "The Glamorgan-Gwent Historic Environment Record (PRN 02038s) independently confirms that Great House Farm was suddenly and completely demolished by B.P. Properties Ltd. on 6th December 1988 amid considerable local controversy. The record documents the 800-year history of the site, including the medieval finds, Vaughan family tenure, Bute Estate ownership, and the disputed demolition. The HER cross-references the RCAHMW Inventory Vol IV Part 2 and provides official archaeological corroboration of the family account.", "scenes": [{"character": "HER OFFICER", "icon": "archive", "side": "left", "color": "#2d5016", "text": "Great House Farm was suddenly and completely demolished by B.P. Properties Ltd. on 6th December 1988 amid considerable local controversy.", "position": {"x": 0, "y": 0}}, {"character": "RCAHMW INVENTOR", "icon": "archive", "side": "right", "color": "#6b3a1f", "text": "Classified as a sub-medieval house of direct-entry type — plan not published due to incomplete information from the 1974 survey.", "position": {"x": 0, "y": 0}}, {"character": "HER OFFICER", "icon": "archive", "side": "left", "color": "#2d5016", "text": "The record documents C12th-C14th pottery, medieval ironwork, Vaughan family tenure, and Bute Estate acquisition.", "position": {"x": 0, "y": 0}}, {"character": "ARCHAEOLOGIST", "icon": "worker", "side": "right", "color": "#4a2d70", "text": "Seven related archaeological events from 1990 to 2013 will follow this official record.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s via Archwilio (https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT02038s)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["HER PRN 02038s: suddenly and completely demolished by B.P. Properties Ltd. on 6th December 1988", "Demolition occurred amid considerable local controversy", "Cross-references RCAHMW Inventory Vol IV Part 2", "Official record compiled 21 Aug 1991, last updated 13 Oct 2023"], "report": []}}, {"id": "ghf-19881212-1", "date": "1988-12-12", "year": "1988", "location": "Great House Farm — Demolition Rubble", "locationType": "other", "description": "", "narration": "In December 1988 R.F. Suggett of the Royal Commission examines the rubble. He records a fireplace jamb, an ogee-stopped beam with torus (a form uncommon in Glamorgan), and the loss of the carved dressed-stone capital kept by the front door, presumably from the old church.", "scenes": [{"character": "R.F. SUGGET", "icon": "archive", "side": "left", "color": "#4a2d70", "text": "A fireplace jamb has since been found in the rubble. The carved stone capital by the front door was lost during demolition.", "position": {"x": 0, "y": 0}}, {"character": "RCAHMW OFFICER", "icon": "archive", "side": "right", "color": "#6b3a1f", "text": "The ogee-stopped beam with torus is a form of decoration not particularly common in Glamorgan. Lost now.", "position": {"x": 0, "y": 0}}, {"character": "R.F. SUGGET", "icon": "archive", "side": "left", "color": "#4a2d70", "text": "The capital by the front door presumably came from the old church. Now it is gone along with the house.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL OBSERVER", "icon": "worker", "side": "right", "color": "#999", "text": "Examination of the rubble brought to light no new features except the ogee-stopped beam with torus.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s — Supplementary Notes (R.F. Sugget, December 1988)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["Fireplace jamb since found in rubble after demolition", "Carved dressed-stone capital by front door — presumably from old church — lost during demolition", "Ogee-stopped beam with torus found in rubble — uncommon in Glamorgan (Inventory Map 50)", "Report by R.F. Sugget, December 1988"], "report": []}}, {"id": "ghf-19890115-1", "date": "1989-01-15", "year": "1989", "location": "Court", "locationType": "other", "description": "", "narration": "In January 1989 the Crown Prosecution Service withdraws, as out of time, a summons alleging threatening behaviour on 29 April 1988. The charges of assault and wanton and furious driving from November remain, and Billy is ordered not to go within half a mile of the site.", "scenes": [{"character": "PROSECUTOR CLARKE", "icon": "worker", "side": "left", "color": "#999", "text": "We withdraw the threatening-behaviour count as the summons is late.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "Even so, I am still barred from going near the former farm site.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "They evict us by force, then prosecute me for resisting their violence!", "position": {"x": 0, "y": 0}}, {"character": "PROSECUTOR CLARKE", "icon": "worker", "side": "right", "color": "#999", "text": "The court order was lawful. Your resistance constituted criminal conduct.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "Nothing about this was lawful! Ownership was never proven!", "position": {"x": 0, "y": 0}}], "sources": ["'Charge against evicted farmer dropped', January 1989 (transcript GHF-E090-N12: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n12)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19890320-1", "date": "1989-03-20", "year": "1989", "location": "Demolition Site", "locationType": "other", "description": "", "narration": "On 20 March 1989 lorries move onto the site at 7.30am to clear the rubble; the operation takes several days.", "scenes": [{"character": "SITE MANAGER", "icon": "worker", "side": "left", "color": "#999", "text": "Our job is simple: remove all remnants so the site is ready for housing.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL HISTORIAN", "icon": "worker", "side": "right", "color": "#999", "text": "They're erasing the last physical evidence of what happened here.", "position": {"x": 0, "y": 0}}, {"character": "SITE MANAGER", "icon": "worker", "side": "left", "color": "#999", "text": "We follow orders. The site must be cleared for redevelopment.", "position": {"x": 0, "y": 0}}, {"character": "LOCAL HISTORIAN", "icon": "worker", "side": "right", "color": "#999", "text": "Rubble removal completes the destruction—house, history, heritage, gone.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 20 March 1989 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19890323-1", "date": "1989-03-23", "year": "1989", "location": "Court", "locationType": "other", "description": "", "narration": "On 23 March 1989 Billy pleads guilty to the remaining charges and is freed. He vows to fight on over the loss of his home and more than 70 acres of land.", "scenes": [{"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "I will go on challenging how our home and the land were taken from us.", "position": {"x": 0, "y": 0}}, {"character": "JUDGE", "icon": "lawyer", "side": "right", "color": "#999", "text": "The matter is concluded. The property has been demolished.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "Demolished, yes—but the fraud, the missing deeds, the suppressed archaeology remain!", "position": {"x": 0, "y": 0}}, {"character": "JUDGE", "icon": "lawyer", "side": "right", "color": "#999", "text": "Those are civil matters beyond this court's criminal jurisdiction.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "left", "color": "#999", "text": "Justice demands investigation! Someone must examine what happened here!", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 23 and 24 March 1989 (transcript GHF-E090-N15: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n15)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19890325-1", "date": "1989-03-25", "year": "1989", "location": "Temporary Accommodation", "locationType": "other", "description": "", "narration": "The family live with Billy's sister in Penarth. Billy plans to convert an old bus into a home, and says about £30,000 of his possessions were taken from the site after the demolition.", "scenes": [{"character": "BILLY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "They have taken everything from me and my family. I have lost my livelihood.", "position": {"x": 0, "y": 0}}, {"character": "BRANWEN BUCKLER", "icon": "worker", "side": "right", "color": "#999", "text": "We have three children, and another on the way.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "worker", "side": "left", "color": "#999", "text": "I shall just have to start from scratch.", "position": {"x": 0, "y": 0}}], "sources": ["South Wales Echo, 1989, 'From farm to a bus', Peter Collins (transcript GHF-E090-N13: https://greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/#n13)", "Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19890414-1", "date": "1989-04-14", "year": "1989", "location": "European Commission of Human Rights", "locationType": "other", "description": "", "narration": "On 14 April 1989 the European Commission accepts that the possession order interfered with William Buckler's home, but holds it lawful and justified, and declares the application inadmissible.", "scenes": [{"character": "COMMISSION", "icon": "lawyer", "side": "left", "color": "#999", "text": "The interference was lawful and justified. The application is inadmissible.", "position": {"x": 0, "y": 0}}, {"character": "BILLY BUCKLER", "icon": "farmer", "side": "right", "color": "#999", "text": "They admit it was my home, and still say it was lawful.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19891010-1", "date": "1989-10-10", "year": "1989", "location": "HM Land Registry — WA513690", "locationType": "other", "description": "", "narration": "On 10 October 1989 BP sells Oakview (title WA513690). How this land relates to the two parcels is unclear.", "scenes": [{"character": "CONVEYANCER", "icon": "lawyer", "side": "left", "color": "#999", "text": "BP Properties sells Oakview, title WA513690.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "We need to plot that title against the farm boundaries.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#later-dealings)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19891107-1", "date": "1989-11-07", "year": "1989", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "In October–November 1989 BP lodges outline application 89/01396/OUT for housing. The planning report records that buildings the Local Plan said should be kept had already been demolished. Outline permission follows on 13 March 1990, with 18 conditions.", "scenes": [{"character": "PLANNING OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "The buildings the Local Plan wanted kept have already gone.", "position": {"x": 0, "y": 0}}, {"character": "COUNCILLOR", "icon": "worker", "side": "right", "color": "#999", "text": "Then there is nothing left to protect but the ground.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19891108-1", "date": "1989-11-08", "year": "1989", "location": "GGAT — Consultee Report", "locationType": "other", "description": "", "narration": "In its report on BP's outline application, GGAT advises that the application should not be decided without an archaeological assessment, specifies the trenching, prices the work at £2,000 over two weeks, and discloses negotiations with BP's agents. BP then commissions GGAT to do the work. The same report describes the farmhouse as having been listed as a 'county treasure'.", "scenes": [{"character": "GGAT", "icon": "archive", "side": "left", "color": "#999", "text": "Assessment needed: machine trenching, two weeks, about two thousand pounds.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The adviser to the council became the contractor to BP in the same breath.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)", "Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19900208-1", "date": "1990-02-08", "year": "1990", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "On 8 February 1990 GGAT sends further comments on the outline application (Appendix B). They are missing from the planning file.", "scenes": [{"character": "PLANNING CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "The file refers to further GGAT comments as Appendix B.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "But Appendix B is not in the file we were given.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Redevelopment and Church View Close (greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19900313-1", "date": "1990-03-13", "year": "1990", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "On 13 March 1990 outline permission is granted with 18 conditions, including archaeological access, evaluation and mitigation. The officer's report had noted that the Local Plan said the farm buildings should be retained, but 'they were unfortunately demolished a little while ago'. No building preservation notice had ever been served.", "scenes": [{"character": "PLANNING OFFICER", "icon": "worker", "side": "left", "color": "#999", "text": "The buildings should be retained. However, they were unfortunately demolished a little while ago.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The plan said keep them. BP knocked them down first, and the council moved on.", "position": {"x": 0, "y": 0}}], "sources": ["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)", "Legal Review, section 4.4 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#criticism-register)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19900801-1", "date": "1990-08-01", "year": "1990", "location": "GGAT Field Evaluation", "locationType": "other", "description": "", "narration": "In August 1990 GGAT digs eight machine trenches for BP. The eastern area 'could not be investigated', yet is zoned low potential. Early-medieval burials are found.", "scenes": [{"character": "GGAT ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "Eight trenches. The eastern area could not be investigated.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "So how could it be called low potential?", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19901015-1", "date": "1990-10-15", "year": "1990", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "On 15 October 1990 the council records condition 17, the archaeological evaluation, as complied with, on the strength of GGAT's eight-trench evaluation of August.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Ground that could not be investigated was signed off as low potential.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "And four years later the burials were found right there.", "position": {"x": 0, "y": 0}}], "sources": ["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19910821-1", "date": "1991-08-21", "year": "1991", "location": "Glamorgan-Gwent HER", "locationType": "archive", "description": "", "narration": "The Glamorgan-Gwent Historic Environment Record compiles its official record of Great House Farm (PRN 02038s), synthesising archaeological assessments, the RCAHMW Inventory, and the supplementary notes of R.F. Sugget. This is followed by the first related archaeological event — an assessment of land at Great House Farm in 1990 (GGATE000877). The HER record will become the definitive archaeological account of the site, independently corroborating the demolition and documenting eight centuries of history.", "scenes": [{"character": "HER COMPILER", "icon": "archive", "side": "left", "color": "#2d5016", "text": "PRN 02038s is now compiled. It records eight centuries of history at Great House Farm.", "position": {"x": 0, "y": 0}}, {"character": "ARCHAEOLOGICAL ASSESSOR", "icon": "worker", "side": "right", "color": "#4a2d70", "text": "Land at Great House Farm: an archaeological assessment is commissioned for 1990.", "position": {"x": 0, "y": 0}}, {"character": "HER COMPILER", "icon": "archive", "side": "left", "color": "#2d5016", "text": "The record cross-references the RCAHMW Inventory Vol IV Part 2 and seven related events through 2013.", "position": {"x": 0, "y": 0}}, {"character": "HER OFFICER", "icon": "archive", "side": "right", "color": "#2d5016", "text": "This official record independently corroborates the demolition on 6 December 1988.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT HER PRN 02038s — Compiled 21-08-1991", "GGATE000877: Great House Farm Archaeological Assessment (1990)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": ["HER PRN 02038s compiled 21 Aug 1991, last updated 13 Oct 2023", "Seven related archaeological events: 1990 (two events), 1994, 2006, 2010 (two events), 2013", "Events include assessments, excavations and evaluations of Great House Farm and environs"], "report": []}}, {"id": "ghf-19920514-1", "date": "1992-05-14", "year": "1992", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "On 14 May 1992 Ideal Homes Wales applies for approval of 20 detached houses on the farm site (92/00671/RES), more than a year before BP transfers the land to it.", "scenes": [{"character": "IDEAL HOMES WALES", "icon": "worker", "side": "left", "color": "#999", "text": "Twenty detached houses, on the former farm site.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "Applied for before the land had been transferred. On what interest?", "position": {"x": 0, "y": 0}}], "sources": ["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19920515-1", "date": "1992-05-15", "year": "1992", "location": "Llandough", "locationType": "other", "description": "", "narration": "William (Billy) Buckler dies at Llandough Hospital on 15 May 1992 after a heart attack. He is buried at Michaelston-le-Pit after a funeral at Bethesda Chapel, Dinas Powys. He had been born in the farmhouse and defended it to the end.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Billy was born in that house and fought for it all his life. He did not live to see the truth come out.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "left", "color": "#999", "text": "We carry on for him.", "position": {"x": 0, "y": 0}}], "sources": ["The Williams / Buckler Family (https://greathousefarmwiki.wordpress.com/williams-buckler-family/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19920727-1", "date": "1992-07-27", "year": "1992", "location": "GGAT", "locationType": "other", "description": "", "narration": "On 27 July 1992 GGAT warns the council that the 1990 assessment showed significant archaeological deposits, including medieval and possibly earlier material and human bone, and urges mitigation. Page 2 of the letter is missing from the file.", "scenes": [{"character": "GGAT", "icon": "archive", "side": "left", "color": "#999", "text": "Significant deposits, including human bone. Mitigation is needed.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "And the second page of that warning is gone.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT — Forensic Review v4.0.3, Test 9 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19920903-1", "date": "1992-09-03", "year": "1992", "location": "Vale of Glamorgan Planning", "locationType": "other", "description": "", "narration": "On 3 September 1992, 38 days after GGAT's warning, the reserved matters for 20 houses are approved with no new archaeological condition. GGAT then records no act on the site for 466 days.", "scenes": [{"character": "COUNCIL", "icon": "worker", "side": "left", "color": "#999", "text": "Reserved matters approved.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Thirty-eight days after the warning about human bone. No new condition.", "position": {"x": 0, "y": 0}}], "sources": ["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)", "GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19931203-1", "date": "1993-12-03", "year": "1993", "location": "Former Farm Site", "locationType": "other", "description": "", "narration": "On 3 December 1993 BP transfers the site to Ideal Homes, and groundworks begin before the archaeological condition has been met.", "scenes": [{"character": "SITE FOREMAN", "icon": "worker", "side": "left", "color": "#999", "text": "Groundworks start Monday.", "position": {"x": 0, "y": 0}}, {"character": "GGAT ARCHAEOLOGIST", "icon": "archive", "side": "right", "color": "#999", "text": "Not before the archaeological condition is met.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19931213-1", "date": "1993-12-13", "year": "1993", "location": "GGAT / Vale of Glamorgan", "locationType": "other", "description": "", "narration": "On 13 December 1993, with groundworks already under way, GGAT recommends urgent consideration of a breach-of-condition notice, saying condition 18 has not been fulfilled. The developer relies on counsel's opinion that it has been discharged, and the council accepts that, later telling the MP it was 'a difference of opinion'.", "scenes": [{"character": "GGAT", "icon": "archive", "side": "left", "color": "#999", "text": "Condition 18 has not been fulfilled. A breach notice should be considered urgently.", "position": {"x": 0, "y": 0}}, {"character": "COUNCIL", "icon": "worker", "side": "right", "color": "#999", "text": "A difference of opinion.", "position": {"x": 0, "y": 0}}], "sources": ["Redevelopment (https://greathousefarmwiki.wordpress.com/redevelopment/)", "Legal Review, section 4.4 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#criticism-register)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19940421-1", "date": "1994-04-21", "year": "1994", "location": "Cemetery Excavation, Former Farm Site", "locationType": "other", "description": "", "narration": "From 21 April to at least 3 May 1994 the Home Office licence to remove human remains has lapsed while work goes on. On 28 April GGAT's officer orders the excavation contractor to do 'no further work' until a brief is approved; under what authority is still unidentified. Removing remains without a licence was an offence under the Burial Act 1857.", "scenes": [{"character": "GGAT OFFICER", "icon": "archive", "side": "left", "color": "#999", "text": "No further work until the brief is approved.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "The licence had lapsed. What was lifted in those days, and on whose say-so?", "position": {"x": 0, "y": 0}}], "sources": ["GGAT — Forensic Review v4.0.3, Tests 8 and 10 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19940504-1", "date": "1994-05-04", "year": "1994", "location": "Cemetery Excavation, Former Farm Site", "locationType": "other", "description": "", "narration": "In 1994, after a Home Office licence (21 March) and agreement to 'preservation by record', the Cotswold Archaeological Trust excavates an early-medieval cemetery on the former farm site. Burials are found in the zone GGAT's 1990 evaluation had called low potential, many just below the topsoil. Published totals reach 1,026 burials, the largest early-medieval burial population then recovered from Wales.", "scenes": [{"character": "LEAD ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "This is an early-medieval cemetery, and a very large one.", "position": {"x": 0, "y": 0}}, {"character": "WILLIAMS DESCENDANT", "icon": "farmer", "side": "right", "color": "#999", "text": "And the 1990 report said this ground was low potential.", "position": {"x": 0, "y": 0}}, {"character": "ARCHAEOLOGIST", "icon": "archive", "side": "left", "color": "#999", "text": "Many burials are only centimetres below the topsoil.", "position": {"x": 0, "y": 0}}, {"character": "LEAD ARCHAEOLOGIST", "icon": "archive", "side": "right", "color": "#999", "text": "This is one of the largest burial grounds ever excavated in Wales.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "CHALLENGE: The site was developed into 20 houses, permanently erasing the physical evidence. No public inquiry was held into the demolition or the family's eviction."}, {"id": "ghf-19940728-1", "date": "1994-07-28", "year": "1994", "location": "National Museum of Wales", "locationType": "other", "description": "", "narration": "On 28 July 1994 Ideal Homes Wales, as landowner, donates the excavated human remains and finds from 'Great House Farm, Llandough' to the National Museum (accession 95.56H). Ownership of finds follows ownership of the land.", "scenes": [{"character": "MUSEUM", "icon": "archive", "side": "left", "color": "#999", "text": "Accession 95.56H: Great House Farm, Llandough. Donated by Ideal Homes Wales.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "If the house parcel was ours, so were the finds from it.", "position": {"x": 0, "y": 0}}], "sources": ["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)", "Legal Review, section 2.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/#land)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19941110-1", "date": "1994-11-10", "year": "1994", "location": "Woodland — WA735527", "locationType": "other", "description": "", "narration": "On 10 November 1994 the woodland, title WA735527, is transferred to Forest of Cardiff. The wiki places the woodland in Parcel A.", "scenes": [{"character": "CONVEYANCER", "icon": "lawyer", "side": "left", "color": "#999", "text": "The woodland title passes to Forest of Cardiff.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "That is the half of the land we are asking to have back.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Woodland (greathousefarmwiki.wordpress.com/woodland/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-19950628-1", "date": "1995-06-28", "year": "1995–96", "location": "HM Land Registry — WA231076 File", "locationType": "other", "description": "", "narration": "Rights are granted to South Wales Electricity, and there is correspondence with Persimmon. This is the last dealing on the registration file.", "scenes": [{"character": "LAND REGISTRY CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "The last entries on the file are the electricity rights and the Persimmon letters.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Then the paper trail on this title stops in the mid-1990s.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Land Registry Titles (greathousefarmwiki.wordpress.com/land-registry-titles/#later-dealings)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20050101-1", "date": "2005-01-01", "year": "2005", "location": "Medieval Archaeology", "locationType": "other", "description": "", "narration": "The 1994 excavation is published in Medieval Archaeology: 1,026 burials in all, 814 of them articulated. The publication tells the story of the cemetery; it does not tell the story of the family whose home stood beside it.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "One of the largest early-medieval cemeteries in Wales, found on the farm's ground.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "And not a word about the family who lived there.", "position": {"x": 0, "y": 0}}], "sources": ["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)", "Holbrook and Thomas, Medieval Archaeology 49 (2005)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20051222-1", "date": "2005-12-22", "year": "2005", "location": "Woodland — WA735527", "locationType": "other", "description": "", "narration": "On 22 December 2005 part of the woodland title is divided off.", "scenes": [{"character": "LAND REGISTRY CLERK", "icon": "archive", "side": "left", "color": "#999", "text": "Part of the woodland is split off into a separate title.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "One more change to trace on the Parcel A land.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Woodland (greathousefarmwiki.wordpress.com/woodland/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20190320-1", "date": "2019-03-20", "year": "2019", "location": "RCAHMW National Archive", "locationType": "other", "description": "", "narration": "On 20 March 2019 GGAT's 1990 assessment is accessioned to the national record, about 28 years after it was written.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "The 1990 Great House Farm assessment, accessioned today.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Twenty-eight years later. Where was it all that time?", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (greathousefarmwiki.wordpress.com)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20251117-1", "date": "2025-11-17", "year": "2025", "location": "Royal Commission (RCAHMW)", "locationType": "other", "description": "", "narration": "In November 2025 the family's records campaign begins. The Royal Commission says it cannot advise on a legal case but holds archives on the site; Llandough Community Council says it cannot help; the Vale of Glamorgan refers the family's request about BP v Buckler to its Information Governance team.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "We start asking every public body what it holds.", "position": {"x": 0, "y": 0}}, {"character": "RECORDS OFFICER", "icon": "archive", "side": "left", "color": "#999", "text": "We hold archives on the site, but we cannot advise on a legal case.", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260123-1", "date": "2026-01-23", "year": "2026", "location": "Cadw / Welsh Government", "locationType": "other", "description": "", "narration": "On 23 January 2026 the family's records request to Cadw bounces: cadw@gov.wales and foi@gov.wales both return 'address not found'. Cadw's published addresses will fail to deliver the family's mail at least eight times this year. On 29 January the family apply to HM Land Registry to record the interest left out at first registration.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The address on Cadw's own website does not work.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Eight failed deliveries to Cadw before the year is out.", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260323-1", "date": "2026-03-23", "year": "2026", "location": "HM Land Registry", "locationType": "other", "description": "", "narration": "On 23 March 2026 HM Land Registry sets out the registration history of Tŷ Mawr Farm and says there is 'no evidence of a mistake in the register'. It treats the farm as one holding and does not explain the root of title to the house parcel.", "scenes": [{"character": "HM LAND REGISTRY", "icon": "lawyer", "side": "left", "color": "#999", "text": "There is no evidence of a mistake in the register.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Then show us the deed that put our house in BP's title.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260419-1", "date": "2026-04-19", "year": "2026", "location": "HM Land Registry", "locationType": "other", "description": "", "narration": "On 19 April 2026 the stage-one complaint is rejected: the Land Registry says it cannot look behind the 1987 judgment. On 25 May the stage-two decision says the title has been 'registered correctly'. Both decisions rest on a judgment that decided possession, not on any deed to the farmhouse.", "scenes": [{"character": "LAND REGISTRAR", "icon": "lawyer", "side": "left", "color": "#999", "text": "The title has been registered correctly. There are no grounds for rectification or indemnity.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "You relied on a judgment that came after the registration and never looked at title.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260521-1", "date": "2026-05-21", "year": "2026", "location": "Cadw Listed Buildings", "locationType": "other", "description": "", "narration": "On 21 May 2026 Cadw releases two photographs from 29 July 1988, coded 'YYY', which it says means 'marginally below the bar'. It has no other electronic record, says the paper files are 'quite likely' destroyed, and promises a search. On 2 and 10 July its review says the file has 'most likely' been destroyed, though no destruction record exists.", "scenes": [{"character": "CADW", "icon": "cleric", "side": "left", "color": "#999", "text": "The paper files have most likely been destroyed.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Most likely? With no record of destruction at all?", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)", "Cadw — Forensic Critique v8.0.0 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/cadw-forensic-critique-v8-0-0/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260602-1", "date": "2026-06-02", "year": "2026", "location": "HM Land Registry", "locationType": "other", "description": "", "narration": "On 2 and 3 June 2026 the family ask to inspect the original Land Registry files and ask that nothing be destroyed while the matter is open. The request goes unanswered in substance for months, and several Registry addresses bounce.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Let us see the originals, and do not destroy them.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Still no substantive answer by the end of September.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260730-1", "date": "2026-07-30", "year": "2026", "location": "HM Land Registry", "locationType": "other", "description": "", "narration": "On 30 July 2026, six months after the first request, the Land Registry releases a schedule of the 43 documents on the first-registration files. The 31 December 1969 conveyance, recited as BP's root of title, is not among them, nor is the 1971 abstract.", "scenes": [{"character": "HM LAND REGISTRY", "icon": "lawyer", "side": "left", "color": "#999", "text": "Forty-three documents survive on the two files.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "And the one deed BP's title rests on is not one of them.", "position": {"x": 0, "y": 0}}], "sources": ["Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#deeds-before-registration)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260825-1", "date": "2026-08-25", "year": "2026", "location": "Amgueddfa Cymru — Museum Wales", "locationType": "other", "description": "", "narration": "On 25 August 2026 the Museum refuses the family's request as 'not held', while saying in the same letter that its searches found records of other discoveries at Great House Farm and Church Farm, which it withholds as 'not in scope'. Those records will be released only on 5 October, after two further request numbers.", "scenes": [{"character": "MUSEUM", "icon": "archive", "side": "left", "color": "#999", "text": "Not held. Other records found are not in scope.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "You found them and kept them back.", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260908-1", "date": "2026-09-08", "year": "2026", "location": "Glamorgan Archives", "locationType": "other", "description": "", "narration": "On 8 September 2026 Glamorgan Archives reply that they hold no deeds for the 1877 Daniel Thomas transaction, but point to Bute X.6(12), the Bute trustees' 1877 abstract of payments and receipts, now at Cardiff Library. A capital payment from Daniel Thomas in that book would prove the sale.", "scenes": [{"character": "ARCHIVIST, GLAMORGAN ARCHIVES", "icon": "archive", "side": "left", "color": "#999", "text": "Bute X.6(12), payments and receipts for 1877, may be worth searching.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "If Daniel Thomas paid for the house, it will be written there.", "position": {"x": 0, "y": 0}}], "sources": ["The 1877 Agreement (https://greathousefarmwiki.wordpress.com/1877-agreement/#glamorgan-2026-4097b)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260917-1", "date": "2026-09-17", "year": "2026", "location": "Cadw / Welsh Government", "locationType": "other", "description": "", "narration": "On 17 September 2026 the family serve a formal stage-one complaint on Cadw over its 1988 listing decision and the loss of its file. Cadw's own address blocks it; it is re-served on the Chief Inspector on 20 September. On 21 September a Land Registry support agent tells the family the title was 'closed in 2005', contradicting the Registry's own history.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Ten matters, set out in full. We ask Cadw to put things right.", "position": {"x": 0, "y": 0}}, {"character": "HMLR SUPPORT", "icon": "lawyer", "side": "left", "color": "#999", "text": "The title was closed in 2005.", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)", "Land Registry Titles (https://greathousefarmwiki.wordpress.com/land-registry-titles/#hmlr-2026)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260922-1", "date": "2026-09-22", "year": "2026", "location": "Great House Farm Wiki", "locationType": "other", "description": "", "narration": "On 22 September 2026 the family launch the Great House Farm Wiki, a public evidence archive. Every document is shown first, labelled by type, then explained, so that anyone can follow the story on the record. Nothing is kept secret.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Every request, every reply and every refusal now goes on the public record.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Evidence first, then what it means. That is how this story will be told.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki (https://greathousefarmwiki.wordpress.com/)", "Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260923-1", "date": "2026-09-23", "year": "2026", "location": "The National Archives", "locationType": "other", "description": "", "narration": "On 23 September 2026 The National Archives identifies the House of Lords judicial papers in BP Properties Limited v Buckler (YHL/PO/JO/10/11/2536), released on its catalogue only in May 2026. Earlier searches had found nothing.", "scenes": [{"character": "THE NATIONAL ARCHIVES", "icon": "archive", "side": "left", "color": "#999", "text": "Judicial Papers A–C 1–63, item 19: B.P. Properties Limited v Buckler.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The Lords papers were there all along. Now we can read them.", "position": {"x": 0, "y": 0}}], "sources": ["Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260925-1", "date": "2026-09-25", "year": "2026", "location": "Forest of Cardiff — Woodland", "locationType": "other", "description": "", "narration": "On 25 September 2026 the Forest of Cardiff, which holds the woodland title WA735527, offers the family a route to ownership. On 27 September the family decline the terms. No price is recorded for the charity's 1994 acquisition.", "scenes": [{"character": "FOREST OF CARDIFF", "icon": "worker", "side": "left", "color": "#999", "text": "We can offer a route to ownership of the woodland.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The woodland is ours to have back, not to buy back.", "position": {"x": 0, "y": 0}}], "sources": ["Woodland (https://greathousefarmwiki.wordpress.com/woodland/)", "Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260927-1", "date": "2026-09-27", "year": "2026", "location": "Heneb / HM Land Registry", "locationType": "other", "description": "", "narration": "On 27 September 2026 the family lodge a formal complaint with Heneb over GGAT's role from 1982 to 1995 and the heritage record, and refer HM Land Registry to the Independent Complaints Reviewer. On 28 September a preservation notice goes to eleven public bodies. Heneb appoints an investigating officer on 29 September; the Reviewer opens case ICR/090/26.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Every body involved is now on notice: keep every record.", "position": {"x": 0, "y": 0}}, {"character": "HENEB", "icon": "archive", "side": "left", "color": "#999", "text": "An investigating officer has been appointed.", "position": {"x": 0, "y": 0}}], "sources": ["GGAT — Forensic Review v4.0.3 (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/government-public-authority-involvement/ggat-forensic-review-and-evidence-schedule-v4-0-3/)", "Records Access Chronology (https://greathousefarmwiki.wordpress.com/records-access-chronology/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20260929-1", "date": "2026-09-29", "year": "2026", "location": "Cadw / RCAHMW", "locationType": "other", "description": "", "narration": "On 29 September 2026 Cadw's complaints investigation begins. The same day the Royal Commission answers four requests together (RC26-0375). Its archive holds a 1974 newspaper report and an older note of the story of a soldier in armour found under the dining-room floor, so the story was on record long before the demolition.", "scenes": [{"character": "CADW", "icon": "cleric", "side": "left", "color": "#999", "text": "Your complaint is now under investigation.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "right", "color": "#999", "text": "The armour story is older than the demolition. It is on the record from 1974.", "position": {"x": 0, "y": 0}}], "sources": ["Archaeology and Heritage (https://greathousefarmwiki.wordpress.com/archaeology/)", "Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20261003-1", "date": "2026-10-03", "year": "2026", "location": "Great House Farm Wiki — Press Archive", "locationType": "other", "description": "", "narration": "On 3 October 2026 fifteen newspaper cuttings from the family archive, Google Drive and email are transcribed onto the wiki, from the 1891 court report to the 1989 coverage.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Fifteen cuttings transcribed, each with its date and paper.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY RESEARCHER", "icon": "farmer", "side": "right", "color": "#999", "text": "Now the press record can be checked by anyone.", "position": {"x": 0, "y": 0}}], "sources": ["Great House Farm Wiki — Master Timeline (greathousefarmwiki.wordpress.com/timeline/)", "Great House Farm Wiki — Press Archive — Newspaper Transcripts (greathousefarmwiki.wordpress.com/evidence-library/press-archive-transcripts/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20261005-1", "date": "2026-10-05", "year": "2026", "location": "Amgueddfa Cymru — Museum Wales", "locationType": "other", "description": "", "narration": "On 5 October 2026, after three requests and two refusals, the Museum releases the Church Farm file: the 1931 letter and the records of the medieval spur and spearhead found beside the church in 1858.", "scenes": [{"character": "MUSEUM", "icon": "archive", "side": "left", "color": "#999", "text": "Accession 63.24: a rowel spur and a spearhead, Llandough Church Farm, about 1858.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Three requests to get one file. But it is out now, on the record.", "position": {"x": 0, "y": 0}}], "sources": ["GHF-E106-R33 (https://greathousefarmwiki.wordpress.com/records-access-chronology/foi-reply-register/ghf-e106-r33-amgueddfa-cymru-reply-further-collections-search-following-8-september-2026-foi/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-20261006-1", "date": "2026-10-06", "year": "2026", "location": "Legal Review", "locationType": "other", "description": "", "narration": "On 6 October 2026 the family publish a review of the whole record from three angles: fraud, land and human rights. It sets out that the 1974 licence letters were sent weeks before Mary's twelve years of occupation after the 1962 order would have run; that by the 1987 appeal the separate farmhouse title had been merged into BP's main title; and that no document on the record shows how the house parcel ever entered BP's title.", "scenes": [{"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "Every step BP took in 1974 avoided a trial of who owned the house.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The case can be reopened, and we will reopen it.", "position": {"x": 0, "y": 0}}], "sources": ["Legal Review — Fraud, Land and Human Rights (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-99990101-1", "date": "9999-01-01", "year": "present_day", "location": "Where Things Stand", "locationType": "other", "description": "", "narration": "Where things stand. The family's ownership of the house parcel has never been heard on the full evidence. The courts of 1955, 1962, 1974 and the 1980s decided possession, never examining the 1877 agreement, the 1928 change, the 1938 conveyance or the 1939 tenancy. BP demolished the house the morning after Cadw declined to list it, before it could be fully recorded. Key records are missing, and the public bodies are now investigating their own handling of the case.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Possession was decided. Ownership never was.", "position": {"x": 0, "y": 0}}, {"character": "ARCHIVIST", "icon": "archive", "side": "left", "color": "#999", "text": "The documents that decide title have never been before a court.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "The records are coming back, one by one.", "position": {"x": 0, "y": 0}}], "sources": ["Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)", "Legal Review — Fraud, Land and Human Rights (https://greathousefarmwiki.wordpress.com/scrutiny-and-accountability/legal-review-fraud-land-human-rights/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}}, {"id": "ghf-99990102-1", "date": "9999-01-02", "year": "present_day", "location": "What the Family Seek", "locationType": "other", "description": "", "narration": "What the family seek: a ruling that they own the house parcel; possession of the woodland and the green, or reparations where that can no longer be given; reparations for the houses built on family land; the return of estate artefacts; and a true heritage record. Every body involved is being given the chance to put things right before the family goes back to court. The Independent Complaints Reviewer deadline falls about 25 November 2026.", "scenes": [{"character": "FAMILY", "icon": "farmer", "side": "right", "color": "#999", "text": "Give us back what can be given back, and make good what cannot.", "position": {"x": 0, "y": 0}}, {"character": "FAMILY", "icon": "farmer", "side": "left", "color": "#999", "text": "The story is not over. It is being reopened.", "position": {"x": 0, "y": 0}}], "sources": ["Family Reparations & Remedy Roadmap (https://greathousefarmwiki.wordpress.com/family-reparations-remedy-roadmap/)", "Where Things Stand (https://greathousefarmwiki.wordpress.com/where-things-stand/)"], "attachments": {"gallery": [], "legal": [], "news": [], "notes": [], "report": []}, "challenge": "The family's case is that fraud and concealment kept the title documents from the courts, opening the way to reopen the judgment under section 32 of the Limitation Act 1980 and the rule in Takhar v Gracefield."}];
